1	/**
2	 * Real playables used as feed mechanics (phase 2).
3	 *
4	 * Each is a self-contained single-HTML build sitting on the same Render static
5	 * site as this prototype (the `playables-export` repo). We load them by
6	 * relative URL into an <iframe>, so on Render `./pins-v1.html` resolves to the
7	 * sibling file. Debug / -applovin duplicates are intentionally excluded — they
8	 * aren't distinct mechanics.
9	 *
10	 * Local dev: the sibling HTML files don't exist at localhost, so pass
11	 * `?base=https://<your-render-host>/` to point the iframes at the deployed
12	 * bundles while developing the feed shell locally.
13	 */
14	// Build stamp baked by vite (same value as the version badge). Used to
15	// cache-bust mechanic iframe URLs so a redeploy is picked up even by WebViews
16	// (Telegram) that cache same-origin siblings by URL and ignore Cache-Control.
17	declare const __PLATFORM_VERSION__: string;
18	const BUILD_TAG = (typeof __PLATFORM_VERSION__ === 'string' ? __PLATFORM_VERSION__ : 'dev').replace(/[^0-9]/g, '') || 'dev';
19	
20	// Per-mechanic cache-bust version = the content hash of each mechanic's shipped
21	// bundle, published by export-swipe.sh into versions.json and loaded at boot
22	// (setMechanicVersions, fetched no-store). A mechanic's iframe URL changes ONLY
23	// when ITS bundle changes, so unchanged mechanics stay cached across deploys, and
24	// a changed one busts even inside a stale-cached feed (the manifest is always
25	// fetched fresh). Falls back to the feed build tag for anything not in the map.
26	let MECH_VERSIONS: Record<string, string> = {};
27	export function setMechanicVersions(m: Record<string, string> | null | undefined): void {
28	  if (m && typeof m === 'object') MECH_VERSIONS = m;
29	}
30	// Some feed entries REUSE another mechanic's shipped HTML (e.g. a different level of
31	// the same build). id → html basename. Falls back to the id itself.
32	const HTML_ALIAS: Record<string, string> = {
33	  'pins-l3-swipe': 'pins-swipe',   // level-3 pins series rides the same pins-swipe build (?level=3)
34	};
35	function htmlFileFor(id: string): string { return HTML_ALIAS[id] ?? id; }
36	function mechanicVersion(id: string): string {
37	  return MECH_VERSIONS[htmlFileFor(id)] || BUILD_TAG;   // shared HTML → shared cache-bust hash
38	}
39	
40	/** Cover image URL for a feed entry — keyed by the ENTRY id (NOT the aliased
41	 *  html), so an entry that reuses another mechanic's build (e.g. pins-l3-swipe →
42	 *  pins-swipe.html at ?level=3) ships its OWN cover baked at its level. Missing
43	 *  covers fall back to the standard card via the <img> onerror handler. */
44	// Cover aspect bucket for THIS device, set once at boot from the measured slot
45	// aspect (see Feed.pickCoverBucket). '' = tall (~0.55, modern phones), '.c' =
46	// compact (~0.72, iPhone SE / small Android). Covers are baked in both aspects so
47	// the object-fit:fill'd poster registers with the live canvas on either cluster.
48	let coverBucket = '';
49	export function setCoverBucket(suffix: string): void {
50	  coverBucket = suffix === '.c' ? '.c' : '';
51	}
52	// Cover-generation epoch — bump when covers are re-baked WITHOUT a payload change
53	// (the `?v=` below is the payload hash, so it wouldn't bust the WebView cover cache
54	// on its own). cv=2: two-aspect buckets (0.55/0.72). cv=3: re-baked at REAL Telegram
55	// aspects (mobile 0.65 / desktop 0.80) + object-fit:cover.
56	const COVER_EPOCH = 3;
57	export function coverUrl(id: string): string {
58	  let base = new URLSearchParams(location.search).get('base') || './';
59	  if (!base.endsWith('/')) base += '/';
60	  return `${base}${id}.cover${coverBucket}.jpg?v=${mechanicVersion(id)}&cv=${COVER_EPOCH}`;
61	}
62	
63	export interface Playable {
64	  id: string;
65	}
66	
67	export const PLAYABLES: Playable[] = [
68	  { id: 'merge-locked-v1-swipe' },
69	  { id: 'pins-swipe' },
70	  { id: 'marble-sort-swipe' },
71	  { id: 'merge-timepress-v1-swipe' },
72	  { id: 'merge-timepress-v2-swipe' },
73	  { id: 'merge-timepress-no-orders-v1-swipe' },
74	  { id: 'pins-l3-swipe' },                    // level-3 pins as its own 1-level series (spaced away from pins-swipe)
75	  { id: 'short-drama-swipe' },
76	  { id: 'merge-second-board-v1-swipe' },
77	  { id: 'merge-second-board-v2-swipe' },
78	];
79	
80	/** Resolve a playable's HTML URL. Relative by default (same Render site);
81	 *  override the host with `?base=…` for local development. */
82	export function playableUrl(id: string, options: { hostPaused?: boolean; auto?: boolean; series?: string; level?: number } = {}): string {
83	  let base = new URLSearchParams(location.search).get('base') || './';
84	  if (!base.endsWith('/')) base += '/';
