:root {
  --platform-bg: #07090f;
  --platform-bg-rgb: 7, 9, 15;
  /* Shared chrome height: top stories rail now uses it directly. The old bottom
     swipe gutter keeps this var as legacy styling, but it is not mounted. */
  --chrome-zone-h: 88px;
  --gutter-h: var(--chrome-zone-h);
  --gutter-gap: 0px;
  /* Safe-area insets. Default to the OS values via env(); inside a Telegram Mini
     App, telegram.ts OVERRIDES these with Telegram's insets (device + its own
     header) because env() is not populated in Telegram fullscreen. */
  --safe-top: env(safe-area-inset-top);
  --safe-bottom: env(safe-area-inset-bottom);
  --safe-left: env(safe-area-inset-left);
  --safe-right: env(safe-area-inset-right);
  --top-zone-h: calc(var(--chrome-zone-h) + var(--safe-top));
  --top-zone-pad-top: max(11px, calc(var(--safe-top) + 3px));
  /* Bottom swipe-bar height. MUST be defined here (not on .game) so the fixed
     .feed-bar — which is NOT inside a .game — can read it too; otherwise the bar
     collapses to content height and a gap opens above it. */
  --swipebar-h: 58px;
  /* Total bottom-bar footprint = visible bar + the device's bottom safe area, so the
     panel's background reaches the very bottom of the screen (no dark strip under it).
     The tappable button stays within --swipebar-h, above the home-indicator zone. */
  --bar-reserve: calc(var(--swipebar-h) + var(--safe-bottom));
  --story-size: 54px;
  --ease-snap: cubic-bezier(0.22, 0.61, 0.36, 1);
  --dev-phone-aspect-w: 390;
  --dev-phone-aspect-h: 844;
}

@property --level-progress {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
1925:.meta-world__primary,
1938:.meta-world__primary {
.meta-world__primary {
  color: #112011;
  background: linear-gradient(180deg, #8ff0a3, #3ccc78);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.36);
}

.meta-world__ghost {
  color: #fff;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.16);
}

.meta-world__primary:disabled,

