const frame = document.createElement('iframe');
frame.setAttribute('scrolling', 'no');
frame.setAttribute('allow', 'autoplay');
play.appendChild(frame);
ov.appendChild(play);

// Themed fork for sort; everything else (and every fallback) = stock build.
const stockSrc = playableUrl(TPL[b.tpl].playableId, { auto: false });
const pk = PACKS.find((x) => x.id === b.pack) ?? PACKS[0];
let watchdog = 0;
void (async () => {
  let forked = false;
  if (b.tpl === 'sort') {
    const html = await forkedSortHtml(pk);
    if (html && frame.isConnected) {
      try {
        const doc = frame.contentWindow?.document;
        if (doc) { doc.open(); doc.write(html); doc.close(); forked = true; }
      } catch { forked = false; }
    }
  }
  if (!forked) { frame.src = stockSrc; return; }
  // Fork didn't boot (no canvas mounted) → quietly reload the stock build.
  watchdog = window.setTimeout(() => {
    try {
      if (frame.isConnected && !frame.contentWindow?.document.querySelector('canvas')) frame.src = stockSrc;
    } catch { frame.src = stockSrc; }
  }, 5000);
})();

const cleanup = () => {
  window.removeEventListener('message', onMsg);
  window.clearTimeout(watchdog);
  try { frame.src = 'about:blank'; } catch { /* noop */ }
  play.remove();
};

