const isValid = (p: Record<string, unknown>): boolean => {
  if (!Array.isArray(p.items) || p.items.length !== 6 || !p.items.every((c) => typeof c === 'string' && HEX.test(c))) return false;
  for (const k of ['ground', 'edge', 'boardBg', 'body', 'roof']) if (typeof p[k] !== 'string' || !HEX.test(p[k] as string)) return false;
  if (typeof p.prop !== 'string' || !PROPS.includes(p.prop)) return false;
  if (typeof p.name !== 'string' || !p.name.trim()) return false;
  // Marbles must be gameplay-distinguishable: min pairwise RGB distance.
  const rgb = (h: string) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
  const items = (p.items as string[]).map(rgb);
  for (let i = 0; i < items.length; i++)
    for (let j = i + 1; j < items.length; j++) {
      const d = Math.abs(items[i][0] - items[j][0]) + Math.abs(items[i][1] - items[j][1]) + Math.abs(items[i][2] - items[j][2]);
      if (d < 90) return false;
    }
  return true;
};

