      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ pack: resolvePack(packRef), prompt, chat }),
      signal: ctrl.signal,
    });
    window.clearTimeout(timer);
    const data = (await res.json()) as { url?: string; error?: string };
    if (!res.ok || !data.url) { console.log('[island] bake failed:', data.error ?? res.status, '— keeping client-side fork'); return; }
    const now = S.buildings.find((x) => x.slot === slot);
    if (!now || now.pack !== packRef) return;   // slot was rebuilt meanwhile
    now.url = data.url;
    save();
    console.log('[island] hosted:', data.url);
    if (ov.isConnected) toast('Published to hosting ✅');
  } catch (e) {
    console.log('[island] bake unreachable:', String(e), '— keeping client-side fork');
  }
}

