1	/**
2	 * Island meta prototype — the PARALLEL experiment to the diamond meta world
3	 * (feed.ts openMetaWorld). Lives behind the TRIANGLE icon on the feed bar.
4	 *
5	 * Concept ("patchwork island"): the player's island is a showcase of their
6	 * created mechanics. Each mechanic is a building that THEMES its own sector —
7	 * ground tint + props + palette all come from the theme pack, so the island
8	 * grows out of what the player makes instead of being decorated from a catalog.
9	 *
10	 * Prototype scope: island state is still localStorage, while dev-only Vite
11	 * endpoints provide theme generation and bake-on-confirm publishing. Playing a
12	 * building launches the hosted UGC artifact when it exists, with a client-side
13	 * fork/stock build as fallback.
14	 */
15	import { apiIslandBake, apiIslandTheme } from './api';
16	import { coverUrl, playableUrl } from './playables';
17	
18	export interface IslandHostCtx { close(): void; }
19	
20	type TplId = 'sort' | 'merge' | 'pins';
21	type PropKind = 'mushroom' | 'crystal' | 'coral' | 'lollipop' | 'rock';
22	
23	interface Pack {
24	  id: string; name: string; kw: string[];
25	  ground: string; edge: string; boardBg: string;
26	  items: string[]; prop: PropKind; body: string; roof: string;
27	}
28	interface Building {
29	  slot: number; tpl: TplId; pack: string; name: string;
30	  plays: number; likes: number; liked: boolean; fresh?: boolean;
31	  url?: string;   // hosted build (swipe-ugc) — play this instead of the client-side fork
32	}
33	interface IslandState {
34	  tokens: number;
35	  buildings: Building[];
36	  aiPacks?: Record<string, Pack>;   // Claude-generated theme packs, persisted so forks survive reloads
37	  aiSeq?: number;
38	}
39	
40	const PACKS: Pack[] = [
41	  { id: 'forest', name: 'Mushroom forest', kw: ['mushroom', 'forest', 'moss', 'гриб', 'лес', 'мох'],
42	    ground: '#79A155', edge: '#5C7F41', boardBg: '#EAF2DC',
43	    items: ['#D9534F', '#F2E3C6', '#E8A33D', '#8A5A44', '#6FA34B', '#5B8BD8'], prop: 'mushroom', body: '#F2E3C6', roof: '#C94A3D' },
44	  { id: 'neon', name: 'Neon city', kw: ['neon', 'cyber', 'city', 'night', 'неон', 'кибер', 'город', 'ноч'],
45	    ground: '#3A3357', edge: '#5C51A0', boardBg: '#241F38',
46	    items: ['#41E0D0', '#FF5FA2', '#FFD84D', '#8F7FFF', '#9BF6FF', '#FF9350'], prop: 'crystal', body: '#4A4170', roof: '#41E0D0' },
47	  { id: 'sea', name: 'Underwater world', kw: ['water', 'sea', 'ocean', 'fish', 'reef', 'вод', 'мор', 'океан', 'рыб', 'риф'],
48	    ground: '#4E9DB0', edge: '#38798A', boardBg: '#E3F2F5',
49	    items: ['#FF8B7E', '#FFC85C', '#4FC9AE', '#4E8FD0', '#E3789E', '#8E6FE8'], prop: 'coral', body: '#DFF2EE', roof: '#FF8B7E' },
50	  { id: 'candy', name: 'Candy kingdom', kw: ['candy', 'sweet', 'caramel', 'cake', 'слад', 'конфет', 'карамел', 'торт'],
51	    ground: '#DE9FBE', edge: '#B96F92', boardBg: '#FBEFF5',
52	    items: ['#F26FA8', '#7EC9EE', '#F5D96E', '#A98FEF', '#6FDCA4', '#C9E24E'], prop: 'lollipop', body: '#FBEFF5', roof: '#F26FA8' },
53	  { id: 'lava', name: 'Volcano wastes', kw: ['lava', 'volcano', 'fire', 'ash', 'лав', 'вулкан', 'ог', 'пепел'],
54	    ground: '#5A4A47', edge: '#42332F', boardBg: '#F0E4DC',
55	    items: ['#FF7031', '#FFC02E', '#9C4433', '#5E4B48', '#FFE08A', '#4EA6D8'], prop: 'rock', body: '#7A625C', roof: '#FF7031' },
56	];
57	const TPL: Record<TplId, { label: string; ds: string; playableId: string }> = {
58	  sort:  { label: 'Sorting', ds: 'sort items into flasks',        playableId: 'marble-sort-swipe' },
59	  merge: { label: 'Merge',   ds: 'combine and grow the chain',    playableId: 'merge-locked-v1-swipe' },
60	  pins:  { label: 'Pins',    ds: 'pull the pins, catch it all',   playableId: 'pins-swipe' },
61	};
62	const CREATABLE_TPLS: TplId[] = ['sort'];
63	const SLOTS = [{ x: 115, y: 155 }, { x: 275, y: 170 }, { x: 115, y: 395 }, { x: 275, y: 380 }];
64	const STORE_KEY = 'island-proto-v1';
65	const GUEST_REWARD = 25;
66	const REROLL_COST = 30;
67	
68	function loadState(): IslandState {
69	  try {
70	    const raw = localStorage.getItem(STORE_KEY);
71	    if (raw) return JSON.parse(raw) as IslandState;
72	  } catch { /* first run / blocked storage */ }
73	  return { tokens: 120, buildings: [
74	    { slot: 1, tpl: 'sort', pack: 'neon', name: 'Neon sort', plays: 2431, likes: 128, liked: false },
75	  ] };
76	}
77	
78	function esc(t: string): string {
79	  return t.replace(/[<>&"]/g, (c) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' }[c] as string));
80	}
81	function cap(s: string): string { return s.charAt(0).toUpperCase() + s.slice(1); }
82	function levelOf(b: Building): number { return 1 + Math.floor(Math.log10(1 + b.plays)); }
83	
84	// Real theme generation: the vite dev server exposes POST /island-api/theme
85	// (vite.config.ts islandThemeApi), which asks Claude for a theme pack from the
86	// player's prompt. Absent endpoint / no API key / invalid output → null, and
87	// the caller falls back to the keyword presets — generation never blocks play.
88	async function aiTheme(prompt: string, avoid?: string): Promise<Pack | null> {
89	  try {
90	    const apiPack = await apiIslandTheme({ prompt, avoid });
91	    if (apiPack) {
92	      console.log('[island] backend theme:', apiPack.name, apiPack.items.join(' '));
93	      return {
94	        id: apiPack.id ?? '', name: apiPack.name.slice(0, 24), kw: apiPack.kw ?? [],
95	        ground: apiPack.ground, edge: apiPack.edge, boardBg: apiPack.boardBg,
96	        items: apiPack.items, prop: apiPack.prop, body: apiPack.body, roof: apiPack.roof,
97	      };
98	    }
99	
100	    const ctrl = new AbortController();
101	    // Generous: the dev endpoint may route through the Claude Code CLI
102	    // (subscription path), which takes tens of seconds. The UX is async
103	    // anyway — the player can dismiss the sheet and keep browsing.
104	    const timer = window.setTimeout(() => ctrl.abort(), 120000);
105	    const res = await fetch('island-api/theme', {
106	      method: 'POST',
107	      headers: { 'content-type': 'application/json' },
108	      body: JSON.stringify({ prompt, avoid }),
109	      signal: ctrl.signal,
110	    });
111	    window.clearTimeout(timer);
112	    const data = (await res.json()) as Record<string, unknown>;
113	    if (!res.ok) { console.log('[island] dev theme API error:', data.error, '→ preset fallback'); return null; }
114	    const items = data.items as string[];
115	    if (!Array.isArray(items) || items.length !== 6) return null;
116	    console.log('[island] dev theme:', data.name, items.join(' '));
117	    return {
118	      id: '', name: String(data.name).slice(0, 24), kw: [],
119	      ground: String(data.ground), edge: String(data.edge), boardBg: String(data.boardBg),
120	      items, prop: data.prop as PropKind, body: String(data.body), roof: String(data.roof),
121	    };
122	  } catch (e) {
123	    console.log('[island] theme APIs unreachable:', String(e), '→ preset fallback');
124	    return null;
125	  }
126	}
127	
128	function pickPack(txt: string, excl: string | null): Pack {
129	  const t = txt.toLowerCase();
130	  let p = t ? PACKS.find((x) => x.kw.some((k) => t.includes(k))) : undefined;
131	  if (!p || p.id === excl) {
132	    const pool = PACKS.filter((x) => x.id !== excl);
133	    p = pool[Math.floor(Math.random() * pool.length)];
134	  }
135	  return p;
136	}
