138	// ── fork-at-launch (proof of the fork path) ─────────────────────────────────
139	// A created mechanic is a RECIPE (base playable + edits), materialised into a
140	// throwaway fork of the shipped artifact at launch time. The base build is
141	// fetched read-only and never modified. marble-sort is the first base: fully
142	// self-contained single file, all art procedural, marble palette = 6 hex
143	// constants — so the recipe is a palette substitution. Guards:
144	//   * recipe checks the artifact still contains the expected constants
145	//     (base rebuilt incompatibly → recipe is stale → play the stock build);
146	//   * any fetch/transform failure → stock build;
147	//   * boot watchdog in playSeries → stock build if the fork doesn't boot.
148	const SORT_MARBLES = ['#F5C842', '#5BC8D8', '#FF9F43', '#FF7B7B', '#B07BFF', '#7BE87B'];
149	
150	async function forkedSortHtml(pk: Pack, dbg: (m: string) => void): Promise<string | null> {
151	  try {
152	    const src = playableUrl(TPL.sort.playableId, { auto: false });
153	    dbg(`fetch base: ${src}`);
154	    const res = await fetch(src);
155	    if (!res.ok) { dbg(`base fetch failed: HTTP ${res.status} → stock`); return null; }
156	    let html = await res.text();
157	    dbg(`base html: ${html.length} bytes`);
158	    let replaced = 0;
159	    const applyPalette = (text: string): string => {
160	      SORT_MARBLES.forEach((hex, i) => {
161	        const n = text.split(hex).length - 1;
162	        replaced += n;
163	        dbg(`  ${hex} → ${pk.items[i % pk.items.length]} (${n}x)`);
164	        text = text.split(hex).join(pk.items[i % pk.items.length]);
165	      });
166	      return text;
167	    };
168	    // Swipe deploys are shell + external payload; older artifacts are single-file.
169	    // The recipe edits whichever part actually carries the palette.
170	    const tag = html.match(/<script type="module" src="(\.[^"]*payload[^"]*)"><\/script>/);
171	    if (tag) {
172	      const purl = new URL(tag[1], new URL(src, location.href)).href;
173	      dbg(`shape: shell + external payload, fetch: ${purl}`);
174	      const pres = await fetch(purl);
175	      if (!pres.ok) { dbg(`payload fetch failed: HTTP ${pres.status} → stock`); return null; }
176	      let payload = await pres.text();
177	      dbg(`payload: ${payload.length} bytes`);
178	      if (!payload.includes(SORT_MARBLES[0])) { dbg('stale recipe: palette constants not found in payload → stock'); return null; }
179	      payload = applyPalette(payload).split('</script').join('<\\/script');
180	      html = html.replace(tag[0], () => `<script type="module">${payload}</script>`);
181	    } else if (html.includes(SORT_MARBLES[0])) {
182	      dbg('shape: single-file artifact');
183	      html = applyPalette(html);
184	    } else {
185	      dbg('stale recipe: no payload tag and no palette constants in html → stock');
186	      return null;
187	    }
188	    dbg(`palette applied: ${replaced} replacements`);
189	    // The fork boots in an about:blank frame: location.search is empty there, so
190	    // bake the launch params straight into the artifact (part of the recipe).
191	    html = html.split('window.location.search').join('"?auto=0"');
192	    html = html.split('location.search').join('"?auto=0"');
193	    // Insurance for artifacts with other relative refs (video files, covers).
194	    const dir = new URL(src, location.href).href.replace(/\?.*$/, '').replace(/[^/]*$/, '');
195	    html = html.replace('<head>', `<head><base href="${dir}">`);
196	    return html;
197	  } catch (e) {
198	    dbg(`transform error: ${String(e)} → stock (cross-origin base? client fork needs same-origin)`);
199	    return null;
200	  }
201	}
