203	// Same shape the feed's outcomeFromMessage accepts, trimmed to what the swipe
204	// builds actually send ({source:'playable', type:'completed', success}).
205	function outcomeOf(data: unknown): 'won' | 'lost' | null {
206	  if (!data || typeof data !== 'object') return null;
207	  const d = data as Record<string, unknown>;
208	  const type = String(d.type ?? d.event ?? '').toLowerCase();
209	  const outcome = String(d.outcome ?? d.result ?? '').toLowerCase();
210	  const won = d.success === true || outcome === 'won' || outcome === 'win' || outcome === 'success';
211	  const lost = d.success === false || ['lost', 'lose', 'loss', 'fail', 'failed'].includes(outcome);
212	  if (['completed', 'complete', 'game_completed', 'game-completed'].includes(type)) {
213	    if (won) return 'won';
214	    if (lost) return 'lost';
215	  }
216	  if (['won', 'win', 'victory', 'success'].includes(type)) return 'won';
217	  if (['lost', 'loss', 'failed', 'fail'].includes(type)) return 'lost';
218	  return null;
219	}
