224	  const t = `transform="translate(${x},${y})"`;
225	  switch (kind) {
226	    case 'mushroom': return `<g ${t}><rect x="-2.5" y="-4" width="5" height="7" rx="2" fill="#F2E3C6"/><path d="M-7 -3 A7 6 0 0 1 7 -3 Z" fill="${c1}"/><circle cx="-2.5" cy="-6" r="1.3" fill="#fff" opacity=".85"/></g>`;
