228	    case 'coral': return `<g ${t}><circle cx="-4" cy="-2" r="4" fill="${c1}"/><circle cx="3" cy="-5" r="4.5" fill="${c2}"/><circle cx="4" cy="2" r="3.4" fill="${c1}"/></g>`;
229	    case 'lollipop': return `<g ${t}><rect x="-1" y="-3" width="2" height="8" fill="#F2E3C6"/><circle cx="0" cy="-7" r="5" fill="${c1}"/><circle cx="0" cy="-7" r="2.4" fill="${c2}"/></g>`;
230	    case 'rock': return `<g ${t}><polygon points="-7,4 -3,-6 4,-8 8,2 3,5" fill="${c1}"/><polyline points="-2,-2 1,0 0,3" stroke="${c2}" stroke-width="1.6" fill="none"/></g>`;
