246	// Mock board used ONLY as the generation preview (playing uses the real build).
247	function board(tpl: TplId, pk: Pick<Pack, 'items' | 'boardBg' | 'edge'>): string {
248	  const dark = parseInt(pk.boardBg.slice(1, 3), 16) < 100;
249	  const cell = dark ? 'rgba(255,255,255,.14)' : 'rgba(0,0,0,.09)';
250	  let s = `<svg viewBox="0 0 300 170" style="display:block;width:100%"><rect width="300" height="170" fill="${pk.boardBg}"/>`;
251	  if (tpl === 'sort') {
252	    const fills = [[0, 1, 0, 2], [3, 2, 1], [4, 0, 3, 1], [2]];
253	    fills.forEach((tube, i) => {
254	      const x = 42 + i * 60;
255	      s += `<rect x="${x - 17}" y="28" width="34" height="118" rx="15" fill="${cell}" stroke="${pk.edge}" stroke-width="1.6"/>`;
256	      tube.forEach((ci, j) => { s += `<circle cx="${x}" cy="${132 - j * 27}" r="12" fill="${pk.items[ci]}"/>`; });
257	    });
258	  } else if (tpl === 'merge') {
259	    const grid = [[1, 0, 2, -1, 0], [0, 3, -1, 1, 2], [2, -1, 4, 0, 1]];
260	    grid.forEach((row, r) => row.forEach((v, c) => {
261	      const x = 32 + c * 48, y = 38 + r * 48;
262	      s += `<rect x="${x - 20}" y="${y - 20}" width="40" height="40" rx="9" fill="${cell}"/>`;
263	      if (v >= 0) s += `<circle cx="${x}" cy="${y}" r="${9 + v * 2.4}" fill="${pk.items[v]}"/><circle cx="${x - 3}" cy="${y - 3}" r="${(9 + v * 2.4) * 0.3}" fill="#fff" opacity=".35"/>`;
264	    }));
265	  } else {
266	    s += `<line x1="95" y1="20" x2="95" y2="112" stroke="${pk.edge}" stroke-width="4"/>
267	          <line x1="205" y1="20" x2="205" y2="112" stroke="${pk.edge}" stroke-width="4"/>`;
268	    ([[130, 34, 0], [158, 32, 1], [144, 56, 2], [170, 58, 3], [122, 60, 4], [150, 82, 0], [132, 104, 1], [164, 104, 2]] as const)
269	      .forEach((b) => { s += `<circle cx="${b[0]}" cy="${b[1]}" r="12" fill="${pk.items[b[2]]}"/>`; });
270	    s += `<rect x="88" y="112" width="124" height="9" rx="4.5" fill="#AEB4BE" stroke="#7E848E" stroke-width="1.5"/>
271	          <circle cx="222" cy="116.5" r="7" fill="#7E848E"/>
272	          <path d="M110 138 L190 138 L182 164 L118 164 Z" fill="${cell}" stroke="${pk.edge}" stroke-width="1.6"/>`;
273	  }
274	  return s + '</svg>';
275	}
