371	export function renderIslandWorld(ov: HTMLElement, ctx: IslandHostCtx): void {
372	  ensureStyles();
373	  const S = loadState();
374	  let guest = false;
375	  let cur: { slot: number; tpl: TplId; prompt: string; pack: Pack; rerolls: number; ai?: boolean; avoid?: string } | null = null;
376	  let toastTimer = 0;
377	  let generationSeq = 0;
378	  const generationBySlot = new Map<number, number>();
379	
380	  const resolvePack = (id: string): Pack => PACKS.find((x) => x.id === id) ?? S.aiPacks?.[id] ?? PACKS[0];
381	
382	  // Slots with a generation job in flight (player dismissed the sheet and kept
383	  // browsing). Rendered as a construction site; the job auto-builds on arrival.
384	  // In-memory only — a reload during generation simply frees the slot.
385	  const pendingSlots = new Set<number>();
386	
387	  // Bake-on-confirm: after a mechanic is BUILT, ship it through the production
388	  // pipeline (bake → autoplay test → publish to swipe-ugc → per-player bot
389	  // message; the player's chat id comes from the mini-app initData). On success
390	  // the building switches from the client-side fork to the hosted build.
391	  async function bakeAndHost(slot: number, prompt: string): Promise<void> {
392	    const b = S.buildings.find((x) => x.slot === slot);
393	    if (!b || b.tpl !== 'sort' || b.url) return;   // only sort has a bake recipe so far
394	    const packRef = b.pack;
395	    const chat = (window as unknown as { Telegram?: { WebApp?: { initDataUnsafe?: { user?: { id?: number } } } } })
396	      .Telegram?.WebApp?.initDataUnsafe?.user?.id;
397	    try {
398	      const hosted = await apiIslandBake({ pack: resolvePack(packRef), prompt, tpl: 'sort' });
399	      if (hosted?.url) {
400	        const now = S.buildings.find((x) => x.slot === slot);
401	        if (!now || now.pack !== packRef) return;
402	        now.url = hosted.url;
403	        save();
404	        console.log('[island] hosted:', hosted.url, hosted.ready ? '(ready)' : '(deploy pending)');
405	        if (ov.isConnected) toast(hosted.ready === false ? 'Published; hosting is warming up' : 'Published to hosting ✅');
406	        return;
407	      }
408	
409	      const ctrl = new AbortController();
410	      const timer = window.setTimeout(() => ctrl.abort(), 300000);
411	      const res = await fetch('island-api/bake', {
412	        method: 'POST',
413	        headers: { 'content-type': 'application/json' },
414	        body: JSON.stringify({ pack: resolvePack(packRef), prompt, chat }),
415	        signal: ctrl.signal,
416	      });
417	      window.clearTimeout(timer);
418	      const data = (await res.json()) as { url?: string; error?: string };
419	      if (!res.ok || !data.url) { console.log('[island] dev bake failed:', data.error ?? res.status, '— keeping client-side fork'); return; }
420	      const now = S.buildings.find((x) => x.slot === slot);
421	      if (!now || now.pack !== packRef) return;   // slot was rebuilt meanwhile
422	      now.url = data.url;
423	      save();
424	      console.log('[island] dev hosted:', data.url);
425	      if (ov.isConnected) toast('Published to hosting ✅');
426	    } catch (e) {
427	      console.log('[island] bake APIs unreachable:', String(e), '— keeping client-side fork');
428	    }
429	  }
430	
431	  const save = () => { try { localStorage.setItem(STORE_KEY, JSON.stringify(S)); } catch { /* private mode */ } };
432	
433	  ov.innerHTML =
434	    '<div class="isl-head">' +
435	      '<div class="isl-ava">G</div>' +
436	      '<div class="isl-who">' +
437	        '<div class="isl-eyebrow">Island · experiment</div>' +
438	        '<div class="isl-title">My Island</div>' +
439	        '<div class="isl-stat" data-stat></div>' +
440	      '</div>' +
441	      '<div class="isl-wallet">🧩 <span data-tok></span></div>' +
442	      '<button class="isl-close" type="button" aria-label="Close">✕</button>' +
443	    '</div>' +
444	    '<div class="isl-modes">' +
445	      '<button class="isl-mode isl-mode--on" type="button" data-mode="owner">My island</button>' +
446	      '<button class="isl-mode" type="button" data-mode="guest">As a guest</button>' +
447	    '</div>' +
448	    '<div class="isl-worldbox"><svg viewBox="0 0 390 540" preserveAspectRatio="xMidYMid slice"></svg></div>' +
449	    '<button class="isl-cta" type="button" data-guest-cta hidden>Play a series here · +' + GUEST_REWARD + ' 🧩</button>' +
450	    '<div class="isl-scrim" data-scrim></div>' +
451	    '<div class="isl-sheet" data-sheet></div>' +
452	    '<div class="isl-toast" data-toast></div>';
453	
454	  const svg = ov.querySelector('svg') as unknown as SVGSVGElement;
455	  const sheet = ov.querySelector('[data-sheet]') as HTMLElement;
456	  const scrim = ov.querySelector('[data-scrim]') as HTMLElement;
457	
458	  const toast = (t: string) => {
459	    const el = ov.querySelector('[data-toast]') as HTMLElement;
460	    el.textContent = t;
461	    el.classList.add('isl-toast--show');
462	    window.clearTimeout(toastTimer);
463	    toastTimer = window.setTimeout(() => el.classList.remove('isl-toast--show'), 2400);
464	  };
465	
466	  const openSheet = (html: string) => {
467	    sheet.innerHTML = '<div class="isl-grab"></div>' + html;
468	    sheet.classList.add('isl-sheet--show');
469	    scrim.classList.add('isl-scrim--show');
470	  };
471	  const closeSheet = () => {
472	    sheet.classList.remove('isl-sheet--show');
473	    scrim.classList.remove('isl-scrim--show');
474	  };
475	  scrim.addEventListener('click', closeSheet);
476	
477	  function refreshIsland(): void {
478	    let s =
479	      '<rect width="390" height="540" fill="#20627A"/>' +
480	      '<ellipse cx="60" cy="66" rx="46" ry="7" fill="#35798F" opacity=".6"/>' +
481	      '<ellipse cx="330" cy="486" rx="52" ry="8" fill="#35798F" opacity=".6"/>' +
482	      '<ellipse cx="342" cy="46" rx="30" ry="6" fill="#35798F" opacity=".5"/>' +
483	      '<ellipse cx="195" cy="276" rx="176" ry="218" fill="#E4D49E"/>' +
484	      '<ellipse cx="195" cy="274" rx="156" ry="195" fill="#A8C078"/>' +
485	      '<ellipse cx="195" cy="274" rx="50" ry="34" fill="#D9CBA3"/>' +
486	      '<g transform="translate(195,274)"><rect x="-2" y="-26" width="4" height="26" fill="#8A6B4A"/><polygon points="2,-26 26,-21 2,-15" fill="#E8603C"/></g>';
487	    SLOTS.forEach((p, i) => {
488	      const b = S.buildings.find((x) => x.slot === i);
489	      if (!b) {
490	        if (pendingSlots.has(i)) {
491	          s += `<g><ellipse cx="${p.x}" cy="${p.y}" rx="70" ry="52" fill="#C9BC8E" stroke="#8FA662" stroke-width="2" stroke-dasharray="4 6"/>
492	            <g class="isl-plus"><text x="${p.x}" y="${p.y + 3}" text-anchor="middle" font-size="24">🏗️</text></g>
493	            <text x="${p.x}" y="${p.y + 28}" text-anchor="middle" font-size="11" fill="#5C7F41">building…</text></g>`;
494	        } else if (!guest) {
495	          s += `<g class="isl-sector" data-slot="${i}">
496	            <ellipse cx="${p.x}" cy="${p.y}" rx="70" ry="52" fill="#B7C98B" stroke="#8FA662" stroke-width="2" stroke-dasharray="7 7"/>
497	            <g class="isl-plus"><circle cx="${p.x}" cy="${p.y - 6}" r="15" fill="#fff"/>
498	            <text x="${p.x}" y="${p.y - 0.5}" text-anchor="middle" font-size="20" font-weight="700" fill="#E8603C">+</text></g>
499	            <text x="${p.x}" y="${p.y + 26}" text-anchor="middle" font-size="11" fill="#5C7F41">build</text></g>`;
500	        } else {
501	          s += `<ellipse cx="${p.x}" cy="${p.y}" rx="70" ry="52" fill="#B7C98B" opacity=".55"/>`;
502	        }
503	        return;
504	      }
505	      const pk = resolvePack(b.pack);
506	      const offs: Array<[number, number]> = [[-42, 16], [36, 22], [-30, -28], [34, -22]];
507	      const props = offs.map((o, j) => prop(pk.prop, o[0], o[1], pk.items[j % pk.items.length], pk.items[(j + 1) % pk.items.length])).join('');
508	      s += `<g class="isl-sector${b.fresh ? ' isl-sector--new' : ''}" data-b="${i}">
509	        <ellipse cx="${p.x}" cy="${p.y}" rx="70" ry="52" fill="${pk.ground}" stroke="${pk.edge}" stroke-width="2"/>
510	        <g transform="translate(${p.x},${p.y})">${props}<g transform="translate(0,-4)">${house(b.tpl, pk.body, pk.roof)}</g></g>
511	        <g><rect x="${p.x - 56}" y="${p.y + 30}" width="112" height="18" rx="9" fill="rgba(255,255,255,.92)"/>
512	        <text x="${p.x}" y="${p.y + 43}" text-anchor="middle" font-size="10.5" font-weight="600" fill="#26241F">${esc(b.name)}</text></g></g>`;
513	      b.fresh = false;
514	    });
515	    svg.innerHTML = s;
516	    svg.querySelectorAll<SVGElement>('[data-slot]').forEach((g) =>
517	      g.addEventListener('click', () => openCreate(Number(g.dataset.slot))));
518	    svg.querySelectorAll<SVGElement>('[data-b]').forEach((g) =>
519	      g.addEventListener('click', () => openBuilding(Number(g.dataset.b))));
520	    const likes = S.buildings.reduce((a, b) => a + b.likes, 0);
521	    (ov.querySelector('[data-stat]') as HTMLElement).textContent =
522	      `♥ ${likes} · ${S.buildings.length}/${SLOTS.length} mechanics`;
523	    (ov.querySelector('[data-tok]') as HTMLElement).textContent = String(S.tokens);
524	    save();
525	  }
526	
527	  // ── creation flow ──────────────────────────────────────────────────────────
528	
529	  function openCreate(slot: number, replacing?: string): void {
530	    cur = { slot, tpl: 'sort', prompt: '', pack: PACKS[0], rerolls: 1 };
531	    const cards = CREATABLE_TPLS.map((id) =>
532	      `<button class="isl-tcard" type="button" data-t="${id}">
533	        <span class="isl-tcard__pv"><img src="${coverUrl(TPL[id].playableId)}" alt="" onerror="this.style.display='none'"></span>
534	        <span><span class="isl-tcard__nm">${TPL[id].label}</span><br><span class="isl-tcard__ds">${TPL[id].ds}</span></span>
535	      </button>`).join('');
536	    const sub = replacing
537	      ? `Step 1 of 3 · this REPLACES “${esc(replacing)}” — its plays and likes are lost`
538	      : 'Step 1 of 3 · pick a template — the theme comes next';
539	    openSheet(`<h3>${replacing ? 'Rebuild slot' : 'New mechanic'}</h3><div class="isl-sub">${sub}</div>
540	      <div class="isl-tcards">${cards}</div>`);
541	    sheet.querySelectorAll<HTMLElement>('[data-t]').forEach((c) =>
542	      c.addEventListener('click', () => { if (cur) { cur.tpl = c.dataset.t as TplId; stepPrompt(); } }));
543	  }
544	
545	  function stepPrompt(): void {
546	    if (!cur) return;
547	    const chips = ['mushroom forest', 'neon city', 'underwater world', 'candy kingdom', 'volcano wastes']
548	      .map((c) => `<button class="isl-chip" type="button">${c}</button>`).join('');
549	    openSheet(`<h3>${TPL[cur.tpl].label}: theme</h3><div class="isl-sub">Step 2 of 3 · describe the world in your own words</div>
550	      <input class="isl-in" data-prm placeholder="e.g. rainy neon city at night" maxlength="40">
551	      <div class="isl-chips">${chips}</div>
552	      <button class="isl-btn isl-btn--pri" type="button" data-gen>Generate theme ✨</button>`);
553	    const inp = sheet.querySelector('[data-prm]') as HTMLInputElement;
554	    sheet.querySelectorAll<HTMLElement>('.isl-chip').forEach((c) =>
555	      c.addEventListener('click', () => { inp.value = c.textContent || ''; }));
556	    (sheet.querySelector('[data-gen]') as HTMLElement).addEventListener('click', () => {
557	      if (!cur) return;
558	      cur.prompt = inp.value.trim();
559	      stepGen();
560	    });
561	  }
562	
563	  function stepGen(): void {
564	    if (!cur) return;
565	    const req = cur;
566	    const generationId = ++generationSeq;
567	    generationBySlot.set(req.slot, generationId);
568	    pendingSlots.add(req.slot);
569	    refreshIsland();
570	    const steps = ['asking the theme model', 'validating the palette', 'deriving island colors', 'assembling on the engine'];
571	    openSheet(`<h3>Generating…</h3><div class="isl-sub">${esc(req.prompt || 'random theme')}</div>
572	      <ul class="isl-gensteps">${steps.map((x) => `<li><span class="d"></span>${x}</li>`).join('')}</ul>
573	      <div class="isl-swrow"></div>
574	      <button class="isl-btn isl-btn--ghost" type="button" data-dismiss>Keep browsing — build it when ready</button>
575	      <div class="isl-pk" style="margin-top:8px">Generation can take a minute. If you close this, the mechanic is built automatically and the island will show it when it's ready.</div>`);
576	    sheet.querySelector('[data-dismiss]')?.addEventListener('click', () => closeSheet());
577	    const lis = [...sheet.querySelectorAll('.isl-gensteps li')];
578	    const rm = matchMedia('(prefers-reduced-motion: reduce)').matches;
579	    lis.forEach((li, i) => window.setTimeout(() => li.classList.add('done'), rm ? 0 : 350 + i * 520));
580	    const minWait = new Promise<void>((r) => window.setTimeout(() => r(), rm ? 300 : 2400));
581	    void Promise.all([aiTheme(req.prompt, req.avoid), minWait]).then(([pack]) => {
582	      if (generationBySlot.get(req.slot) !== generationId) {
583	        refreshIsland();
584	        return;
585	      }
586	      generationBySlot.delete(req.slot);
587	      pendingSlots.delete(req.slot);
588	      const resolved = pack ?? pickPack(req.prompt, req.pack.id);
589	      const isAi = Boolean(pack);
590	      if (pack) {
591	        pack.id = `ai-${(S.aiSeq = (S.aiSeq ?? 0) + 1)}`;
592	        S.aiPacks = { ...(S.aiPacks ?? {}), [pack.id]: pack };
593	      }
594	      const interactive = ov.isConnected && sheet.classList.contains('isl-sheet--show') && cur === req;
595	      if (interactive) {
596	        req.pack = resolved;
597	        req.ai = isAi;
598	        save();
599	        stepPreview();
600	        return;
601	      }
602	      // Player moved on (sheet dismissed or island closed) — auto-build the
603	      // mechanic with the arrived theme; skip preview/reroll. State is saved
604	      // even if the island overlay is gone, so it's there on the next visit.
605	      const nm = isAi ? resolved.name : (req.prompt ? cap(req.prompt) : resolved.name);
606	      S.buildings = S.buildings.filter((x) => x.slot !== req.slot);
607	      S.buildings.push({ slot: req.slot, tpl: req.tpl, pack: resolved.id, name: nm.slice(0, 16), plays: 0, likes: 0, liked: false, fresh: true });
608	      save();
609	      if (ov.isConnected) {
610	        refreshIsland();
611	        toast(`"${nm.slice(0, 16)}" is ready 🌱`);
612	      }
613	      void bakeAndHost(req.slot, req.prompt);
614	    });
615	  }
616	
617	  function stepPreview(): void {
618	    if (!cur) return;
619	    const pk = cur.pack;
620	    const nm = cur.ai ? pk.name : (cur.prompt ? cap(cur.prompt) : pk.name);
621	    const rl = cur.rerolls > 0 ? 'Reroll · 1 free' : `Reroll · ${REROLL_COST} 🧩`;
622	    openSheet(`<h3>Theme preview</h3><div class="isl-sub">Step 3 of 3 · how the mechanic will look</div>
623	      <div class="isl-board">${board(cur.tpl, pk)}</div>
624	      <div class="isl-pk"><b>${esc(nm)}</b> · ${TPL[cur.tpl].label} · <span style="opacity:.65">${cur.ai ? 'AI theme ✨' : 'preset theme (AI offline)'}</span></div>
625	      <div class="isl-swrow" style="margin-top:8px">${pk.items.map((c) => `<span class="isl-sw isl-sw--in" style="background:${c}"></span>`).join('')}</div>
626	      <button class="isl-btn isl-btn--pri" type="button" data-build>Build on the island</button>
627	      <button class="isl-btn isl-btn--ghost" type="button" data-rr>${rl}</button>`);
628	    (sheet.querySelector('[data-build]') as HTMLElement).addEventListener('click', () => {
629	      if (!cur) return;
630	      const { slot, tpl: tplId, prompt } = cur;
631	      // Slots are the cap: building on an occupied slot replaces its mechanic.
632	      S.buildings = S.buildings.filter((x) => x.slot !== slot);
633	      S.buildings.push({ slot, tpl: tplId, pack: pk.id, name: nm.slice(0, 16), plays: 0, likes: 0, liked: false, fresh: true });
634	      cur = null;
635	      closeSheet();
636	      refreshIsland();
637	      toast('Built! The sector took your theme 🌱');
638	      void bakeAndHost(slot, prompt);
639	    });
640	    (sheet.querySelector('[data-rr]') as HTMLElement).addEventListener('click', () => {
641	      if (!cur) return;
642	      if (cur.rerolls > 0) cur.rerolls--;
643	      else if (S.tokens >= REROLL_COST) { S.tokens -= REROLL_COST; save(); }
644	      else { toast('Not enough tokens'); return; }
645	      (ov.querySelector('[data-tok]') as HTMLElement).textContent = String(S.tokens);
646	      cur.avoid = cur.ai ? cur.pack.name : undefined;
647	      stepGen();
648	    });
649	  }
650	
651	  // ── building card + play (real mechanic in an iframe) ──────────────────────
652	
653	  function openBuilding(slot: number): void {
654	    const b = S.buildings.find((x) => x.slot === slot);
655	    if (!b) return;
656	    if (guest) { playSeries(b); return; }
657	    const pk = resolvePack(b.pack);
658	    openSheet(`<h3>${esc(b.name)}</h3>
659	      <div class="isl-sub">${TPL[b.tpl].label} · Lv ${levelOf(b)} · ${b.plays} plays · ♥ ${b.likes}</div>
660	      <div class="isl-board">${board(b.tpl, pk)}</div>
661	      <button class="isl-btn isl-btn--pri" type="button" data-play>▶ Play the series</button>
662	      <button class="isl-btn isl-btn--ghost" type="button" data-rebuild>Rebuild slot · replace this mechanic</button>
663	      <button class="isl-btn isl-btn--ghost" type="button" data-delete>Delete mechanic</button>
664	      <div class="isl-pk" style="margin-top:10px">Guests like it after they beat it — switch to guest mode to feel it</div>`);
665	    (sheet.querySelector('[data-play]') as HTMLElement).addEventListener('click', () => { closeSheet(); playSeries(b); });
666	    (sheet.querySelector('[data-rebuild]') as HTMLElement).addEventListener('click', () => { closeSheet(); openCreate(slot, b.name); });
667	    (sheet.querySelector('[data-delete]') as HTMLElement).addEventListener('click', () => {
668	      if (!window.confirm(`Delete "${b.name}" from the island?`)) return;
669	      S.buildings = S.buildings.filter((x) => x.slot !== slot);
670	      closeSheet();
671	      refreshIsland();
672	      toast('Mechanic removed from the island');
673	    });
674	  }
675	
676	  function playSeries(b: Building): void {
677	    const play = document.createElement('div');
678	    play.className = 'isl-play';
679	    play.innerHTML =
680	      '<div class="isl-play__head">' +
681	        `<div class="isl-play__nm">${esc(b.name)} <span style="opacity:.55;font-weight:600">· ${TPL[b.tpl].label}</span></div>` +
682	        '<button class="isl-dbg" type="button" data-dbg>boot…</button>' +
683	        '<button class="isl-close" type="button" aria-label="Back" data-back>✕</button>' +
684	      '</div>';
685	    const frame = document.createElement('iframe');
686	    frame.setAttribute('scrolling', 'no');
687	    frame.setAttribute('allow', 'autoplay');
688	    play.appendChild(frame);
689	    ov.appendChild(play);
690	
691	    // Launch telemetry: every step of the fork/fallback path is logged. The
692	    // chip in the header shows the verdict; tapping it opens the full log.
693	    const dbgLines: string[] = [];
694	    const dbg = (m: string) => { dbgLines.push(m); console.log('[island]', m); };
695	    const chip = play.querySelector('[data-dbg]') as HTMLElement;
696	    const setChip = (t: string) => { chip.textContent = t; };
697	    chip.addEventListener('click', () => {
698	      const old = play.querySelector('.isl-dbglog');
699	      if (old) { old.remove(); return; }
700	      const panel = document.createElement('div');
701	      panel.className = 'isl-dbglog';
702	      panel.textContent = dbgLines.join('\n');
703	      play.appendChild(panel);
704	    });
705	    dbg(`launch: "${b.name}" tpl=${b.tpl} pack=${b.pack} guest=${guest}`);
706	
707	    // Themed fork for sort; everything else (and every fallback) = stock build.
708	    const stockSrc = playableUrl(TPL[b.tpl].playableId, { auto: false });
709	    const pk = resolvePack(b.pack);
710	    let watchdog = 0;
711	    void (async () => {
712	      // Hosted build wins over the client-side fork: it's the tested, published
713	      // artifact. Real URL → query params work; no watchdog (cross-origin in
714	      // prod, and the artifact already passed the worker's autoplay gate).
715	      if (b.url) {
716	        dbg(`loading hosted build: ${b.url}`);
717	        setChip(`HOSTED · ${pk.name}`);
718	        frame.src = `${b.url}${b.url.includes('?') ? '&' : '?'}auto=0`;
719	        return;
720	      }
721	      let forked = false;
722	      if (b.tpl === 'sort') {
723	        const html = await forkedSortHtml(pk, dbg);
724	        if (html && frame.isConnected) {
725	          try {
726	            const doc = frame.contentWindow?.document;
727	            if (doc) { doc.open(); doc.write(html); doc.close(); forked = true; }
728	          } catch (e) { dbg(`doc.write failed: ${String(e)}`); forked = false; }
729	        }
730	      } else {
731	        dbg(`no fork recipe for tpl=${b.tpl} yet → stock`);
732	      }
733	      if (!forked) {
734	        dbg(`loading stock: ${stockSrc}`);
735	        setChip(`STOCK · ${b.tpl}`);
736	        frame.src = stockSrc;
737	        return;
738	      }
739	      dbg('fork written into frame');
740	      setChip(`FORK · ${pk.name}`);
741	      // Fork didn't boot (no canvas mounted) → quietly reload the stock build.
742	      watchdog = window.setTimeout(() => {
743	        try {
744	          if (frame.isConnected && !frame.contentWindow?.document.querySelector('canvas')) {
745	            dbg('watchdog: no canvas in 5s → reloading stock');
746	            setChip('STOCK · watchdog');
747	            frame.src = stockSrc;
748	          } else {
749	            dbg('watchdog: canvas mounted, fork is live');
750	          }
751	        } catch (e) {
752	          dbg(`watchdog error: ${String(e)} → stock`);
753	          setChip('STOCK · watchdog');
754	          frame.src = stockSrc;
755	        }
756	      }, 5000);
757	    })();
758	
759	    const cleanup = () => {
760	      window.removeEventListener('message', onMsg);
761	      window.clearTimeout(watchdog);
762	      try { frame.src = 'about:blank'; } catch { /* noop */ }
763	      play.remove();
764	    };
765	    const showWin = () => {
766	      b.plays++;
767	      if (guest) S.tokens += GUEST_REWARD;
768	      const win = document.createElement('div');
769	      win.className = 'isl-win';
770	      win.innerHTML =
771	        '<div class="isl-win__t">Round won! 🎉</div>' +
772	        (guest ? `<div class="isl-win__m">+${GUEST_REWARD} 🧩 for playing on someone's island</div>`
773	               : '<div class="isl-win__m">Your own build — no tokens for self-plays</div>') +
774	        (guest ? `<button class="isl-like${b.liked ? ' isl-like--on' : ''}" type="button" data-like>${b.liked ? '♥ Liked' : '♡ Like this mechanic'}</button>` : '') +
775	        '<button class="isl-win__home" type="button" data-home>Back to island</button>';
776	      play.appendChild(win);
777	      win.querySelector('[data-like]')?.addEventListener('click', (e) => {
778	        const btn = e.currentTarget as HTMLElement;
779	        b.liked = !b.liked;
780	        b.likes += b.liked ? 1 : -1;
781	        btn.classList.toggle('isl-like--on', b.liked);
782	        btn.textContent = b.liked ? '♥ Liked' : '♡ Like this mechanic';
783	        save();
784	      });
785	      (win.querySelector('[data-home]') as HTMLElement).addEventListener('click', () => { cleanup(); refreshIsland(); });
786	      refreshIsland();
787	    };
788	    const onMsg = (e: MessageEvent) => {
789	      if (!ov.isConnected) { cleanup(); return; }
790	      if (e.source !== frame.contentWindow) return;
791	      const d = e.data as Record<string, unknown> | null;
792	      if (d && typeof d === 'object' && d.source === 'playable') dbg(`frame msg: ${String(d.type ?? d.event ?? '?')}`);
793	      const out = outcomeOf(e.data);
794	      if (out === 'won') { dbg('outcome: won'); showWin(); }
795	      else if (out === 'lost') { dbg('outcome: lost'); toast('So close — the mechanic restarts itself'); }
796	    };
797	    window.addEventListener('message', onMsg);
798	    (play.querySelector('[data-back]') as HTMLElement).addEventListener('click', () => { cleanup(); refreshIsland(); });
799	  }
800	
801	  // ── header / modes ─────────────────────────────────────────────────────────
802	
803	  (ov.querySelector('.isl-close') as HTMLElement).addEventListener('click', () => ctx.close());
804	  ov.querySelectorAll<HTMLElement>('[data-mode]').forEach((btn) =>
805	    btn.addEventListener('click', () => {
806	      guest = btn.dataset.mode === 'guest';
807	      ov.querySelectorAll('[data-mode]').forEach((el) =>
808	        el.classList.toggle('isl-mode--on', (el as HTMLElement).dataset.mode === (guest ? 'guest' : 'owner')));
809	      (ov.querySelector('[data-guest-cta]') as HTMLElement).hidden = !guest;
810	      (ov.querySelector('.isl-title') as HTMLElement).textContent = guest ? "Gleb's Island" : 'My Island';
811	      refreshIsland();
812	    }));
813	  (ov.querySelector('[data-guest-cta]') as HTMLElement).addEventListener('click', () => {
814	    const b = S.buildings[Math.floor(Math.random() * S.buildings.length)];
815	    if (b) playSeries(b);
816	  });
817	
818	  refreshIsland();
819	}
