"""Island UGC endpoints: theme generation and bake-on-confirm publishing.

Production shape mirrors the dev Vite rehearsal: generation returns only a
validated theme pack; bake runs the UGC worker after the player confirms the
build, serialised by a process-local lock so git publishes do not overlap.
"""
from __future__ import annotations

import asyncio
import json
import os
import re
import time
from pathlib import Path
from typing import Any, Literal

import httpx
from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, Field, field_validator

from .auth import TmaUser, require_tma_user
from .config import get_settings

router = APIRouter()

HEX_RE = re.compile(r"^#[0-9A-Fa-f]{6}$")
PROPS = {"mushroom", "crystal", "coral", "lollipop", "rock"}
_bake_lock = asyncio.Lock()


def bake_runtime_status() -> dict[str, str]:
    """Operational state for /health; never exposes credentials or repo URLs."""
    s = get_settings()
    if not s.island_bake_ready_file:
        return {"state": "local"}
    if Path(s.island_bake_ready_file).is_file():
        return {"state": "ready"}
    error_file = Path(s.island_bake_error_file) if s.island_bake_error_file else None
    if error_file and error_file.is_file():
        reason = error_file.read_text(encoding="utf-8", errors="replace").strip()[:500]
        return {"state": "failed", "reason": reason or "unknown error"}
    return {"state": "initializing"}


class ThemePack(BaseModel):
    id: str = ""
    name: str = Field(min_length=1, max_length=40)
    kw: list[str] = Field(default_factory=list)
    ground: str
    edge: str
    boardBg: str
    items: list[str] = Field(min_length=6, max_length=6)
    prop: Literal["mushroom", "crystal", "coral", "lollipop", "rock"]
    body: str
    roof: str

    @field_validator("ground", "edge", "boardBg", "body", "roof")
    @classmethod
    def _hex_field(cls, value: str) -> str:
        if not HEX_RE.match(value):
            raise ValueError("must be a #RRGGBB hex color")
        return value

    @field_validator("items")
    @classmethod
    def _items(cls, value: list[str]) -> list[str]:
        if any(not HEX_RE.match(c) for c in value):
            raise ValueError("items must be #RRGGBB hex colors")
        rgbs = [[int(c[i : i + 2], 16) for i in (1, 3, 5)] for c in value]
        for i in range(len(rgbs)):
            for j in range(i + 1, len(rgbs)):
                dist = sum(abs(rgbs[i][k] - rgbs[j][k]) for k in range(3))
                if dist < 90:
                    raise ValueError(f"marble colors {value[i]} and {value[j]} are too similar")
        return value


class ThemeIn(BaseModel):
    prompt: str = Field(default="", max_length=120)
    avoid: str | None = Field(default=None, max_length=60)


class BakeIn(BaseModel):
    pack: ThemePack
    prompt: str = Field(default="", max_length=120)
    tpl: Literal["sort"] = "sort"


def _theme_prompt(prompt: str, avoid: str | None) -> str:
    return f"""You are generating a visual theme pack for a marble-sort puzzle retheme in a mobile game.
Player's theme prompt: "{prompt or 'surprise me'}"
{f'The player rerolled: make this variant clearly different from the previous one named "{avoid}".' if avoid else ''}
Rules:
- items: exactly 6 marble colors. They MUST be instantly distinguishable from each other and readable on the game's dark blue-grey board (#4A5878). Saturated mid-to-bright colors; no near-black, no near-white.
- Colors should evoke the theme.
- ground/edge: the theme's island-sector ground and its darker border.
- boardBg: soft tint for preview cards.
- body/roof: a small building in this theme.
- prop: one of mushroom, crystal, coral, lollipop, rock.
- name: short and evocative, same language as the player's prompt.
Return ONLY the raw JSON object with keys name, items, ground, edge, boardBg, body, roof, prop. No markdown fences, no prose."""


def _extract_json_object(text: str) -> dict[str, Any]:
    match = re.search(r"\{[\s\S]*\}", text)
    if not match:
        raise ValueError("model returned no JSON object")
    value = json.loads(match.group(0))
    if not isinstance(value, dict):
        raise ValueError("model JSON must be an object")
    return value


def _resolve_path(raw: str) -> Path:
    path = Path(raw)
    if path.is_absolute():
        return path
    return (Path(__file__).resolve().parents[1] / path).resolve()


async def _anthropic_theme(prompt: str, avoid: str | None) -> ThemePack:
    s = get_settings()
    if not s.anthropic_api_key:
        raise HTTPException(status_code=503, detail="ANTHROPIC_API_KEY missing")
    last_error = ""
    async with httpx.AsyncClient(timeout=90.0) as client:
        for attempt in range(2):
            full_prompt = _theme_prompt(prompt, avoid)
            if attempt:
                full_prompt += f"\nYour previous attempt was rejected by validation: {last_error}. Fix exactly that while keeping the theme."
            r = await client.post(
                "https://api.anthropic.com/v1/messages",
                headers={
                    "x-api-key": s.anthropic_api_key,
                    "anthropic-version": "2023-06-01",
                    "content-type": "application/json",
                },
                json={
                    "model": s.island_theme_model,
                    "max_tokens": 1000,
                    "messages": [{"role": "user", "content": full_prompt}],
                },
            )
            if r.status_code >= 400:
                raise HTTPException(status_code=502, detail=f"theme model error: HTTP {r.status_code}")
            data = r.json()
            text = "".join(block.get("text", "") for block in data.get("content", []) if block.get("type") == "text")
            try:
                return ThemePack.model_validate(_extract_json_object(text))
            except Exception as e:  # noqa: BLE001 - validation reason is fed back once
                last_error = str(e)
    raise HTTPException(status_code=422, detail=f"pack failed validation twice: {last_error}")


async def _wait_for_hosted(url: str, seconds: int, poll: float) -> bool:
    if not url or seconds <= 0:
        return False
    deadline = time.monotonic() + seconds
    async with httpx.AsyncClient(timeout=8.0, follow_redirects=True) as client:
        while time.monotonic() < deadline:
            try:
                r = await client.head(url)
                if r.status_code == 405:
                    r = await client.get(url, headers={"Range": "bytes=0-0"})
                if 200 <= r.status_code < 400:
                    return True
            except httpx.HTTPError:
                pass
            await asyncio.sleep(max(0.5, poll))
    return False


@router.post("/island/theme")
async def island_theme(body: ThemeIn, _: TmaUser = Depends(require_tma_user)) -> dict:
    pack = await _anthropic_theme(body.prompt.strip(), body.avoid.strip() if body.avoid else None)
    return pack.model_dump()


@router.post("/island/bake")
async def island_bake(body: BakeIn, caller: TmaUser = Depends(require_tma_user)) -> dict:
    s = get_settings()
    runtime = bake_runtime_status()
    if runtime["state"] in {"initializing", "failed"}:
        detail = "bake runtime is still initializing"
        if runtime["state"] == "failed":
            detail = f"bake runtime initialization failed: {runtime.get('reason', 'unknown error')}"
        raise HTTPException(status_code=503, detail=detail)
    repo = _resolve_path(s.ugc_repo_path)
    playables_root = _resolve_path(s.playables_root_path)
    worker = repo / "worker" / "bake.mjs"
    if not worker.exists():
        raise HTTPException(status_code=503, detail=f"bake worker not found at {worker}")
    if not playables_root.exists():
        raise HTTPException(status_code=503, detail=f"playables root not found at {playables_root}")

    async with _bake_lock:
        env = os.environ.copy()
        if s.ugc_base_url:
            env["UGC_BASE_URL"] = s.ugc_base_url
        if s.bot_token:
            env["BOT_TOKEN"] = s.bot_token
        env["PLAYABLES_ROOT"] = str(playables_root)
        proc = await asyncio.create_subprocess_exec(
            "node",
            str(worker),
            "--pack",
            body.pack.model_dump_json(),
            "--prompt",
            body.prompt,
            "--user",
            str(caller.id),
            "--tpl",
            body.tpl,
            "--chat",
            str(caller.id),
            cwd=str(repo),
            env=env,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        try:
            stdout_b, stderr_b = await asyncio.wait_for(proc.communicate(), timeout=s.island_bake_timeout_sec)
        except asyncio.TimeoutError:
            proc.kill()
            await proc.communicate()
            raise HTTPException(status_code=504, detail="bake worker timed out") from None
        stdout = stdout_b.decode(errors="replace")
        stderr = stderr_b.decode(errors="replace")
        if proc.returncode != 0:
            raise HTTPException(status_code=502, detail=(stderr or stdout or "bake worker failed")[-1200:])
        match = re.search(r"^RESULT (\{.*\})$", stdout, re.MULTILINE)
        if not match:
            raise HTTPException(status_code=502, detail="bake worker returned no RESULT line")
        result = json.loads(match.group(1))
        rel = str(result["rel"])
        url = f"{s.ugc_base_url.rstrip('/')}/{rel}" if s.ugc_base_url else ""
        ready = await _wait_for_hosted(url, s.island_deploy_wait_sec, s.island_deploy_poll_sec) if url else False
        return {"rel": rel, "url": url, "ready": ready}

