async def _anthropic_theme(prompt: str, avoid: str | None) -> ThemePack:
    s = get_settings()
    if not s.anthropic_api_key:
        raise HTTPException(status_code=503, detail="ANTHROPIC_API_KEY missing")
    last_error = ""
    async with httpx.AsyncClient(timeout=90.0) as client:
        for attempt in range(2):
            try:
                full_prompt = render_theme_prompt(prompt, avoid)
            except OSError as e:
                raise HTTPException(status_code=503, detail=f"island recipe unavailable: {e}") from None
            if attempt:
                full_prompt += f"\nYour previous attempt was rejected by validation: {last_error}. Fix exactly that while keeping the theme."
            r = await client.post(
                "https://api.anthropic.com/v1/messages",
                headers={
                    "x-api-key": s.anthropic_api_key,
                    "anthropic-version": "2023-06-01",
                    "content-type": "application/json",
                },
                json={
                    "model": s.island_theme_model,
                    "max_tokens": 1000,
                    "messages": [{"role": "user", "content": full_prompt}],
                },
            )
            if r.status_code >= 400:
                raise HTTPException(status_code=502, detail=f"theme model error: HTTP {r.status_code}")
            data = r.json()
            text = "".join(block.get("text", "") for block in data.get("content", []) if block.get("type") == "text")
            try:
                return ThemePack.model_validate(_extract_json_object(text))
            except Exception as e:  # noqa: BLE001 - validation reason is fed back once
                last_error = str(e)
    raise HTTPException(status_code=422, detail=f"pack failed validation twice: {last_error}")


