  sheet.querySelectorAll<HTMLElement>('.isl-chip').forEach((c) =>
    c.addEventListener('click', () => { inp.value = c.textContent || ''; }));
  (sheet.querySelector('[data-gen]') as HTMLElement).addEventListener('click', () => {
    if (!cur) return;
    cur.prompt = inp.value.trim();
    stepGen();
  });
}

