  fixed_lava:  ['#FF7031','#FFDD1C','#9C4433','#5E4B48','#FFE08A','#4EA6D8'],
};
const rgb = h => [1,3,5].map(i => parseInt(h.slice(i,i+2),16));
for (const [name, items] of Object.entries(packs)) {
