let rafGateInstalled = false;
let nativeRequestAnimationFrame: typeof requestAnimationFrame | null = null;
let nativeCancelAnimationFrame: typeof cancelAnimationFrame | null = null;
let nextHostRafId = 1;
const pendingHostRafs = new Map<number, FrameRequestCallback>();
// id → canceller: a scheduled frame is either a native rAF or (during the
// warm-paint window) a throttling setTimeout that leads to one.
const nativeHostRafs = new Map<number, { cancel: () => void }>();

// Warm start-screen paint is opt-in diagnostics only. The feed already rides a
// host-owned cover/poster, so spending background frames to compose an offscreen
// iframe only competes with the mechanic the player can actually see. Keep the
// old timer-driven path behind `?warmpaint=<ms>` for device A/Bs; production
// parks host-paused SWIPE frames immediately. Non-SWIPE targets never install
// this gate and are unaffected.
const WARM_PAINT_MS = (() => {
  if (typeof __SWIPE__ === 'undefined' || !__SWIPE__) return 0;
  try {
    if (typeof location !== 'undefined') {
      const v = new URLSearchParams(location.search).get('warmpaint');
      if (v === 'off') return 0;
      if (v && /^\d+$/.test(v)) return Math.min(4000, parseInt(v, 10));
    }
  } catch { /* noop */ }
  return 0;
})();
let warmPaintUntil = 0;   // wall-clock deadline; armed on the first rAF while host-paused

// True while a warm frame is still inside its start-screen paint window.
function warmPaintAllowed(): boolean {
  return WARM_PAINT_MS > 0 && hostPaused && !hostResumedOnce
    && warmPaintUntil !== 0 && performance.now() < warmPaintUntil;
}
// A queued frame may run if the frame is on-screen OR still painting its warm
// start screen.
function canRunRaf(): boolean {
  return isInteractive() || warmPaintAllowed();
}

function runPauseCallbacks(): void {
  muteAll();
  for (const cb of pauseCallbacks) {
    try { cb(); } catch (e) { console.warn('[lifecycle] pause callback failed', e); }
  }
}

function runResumeCallbacks(): void {
  unmuteAll();
  for (const cb of resumeCallbacks) {
    try { cb(); } catch (e) { console.warn('[lifecycle] resume callback failed', e); }
  }
  flushHostRafs();
}

// During the warm-paint window frames are released at ~5fps, not the native
// 60: a STATIC start screen needs a handful of repaints (first compose + a
// few as decoded images arrive), not a running loop. At native rate the warm
// frame's full-board redraws (~10-30ms each on a mid Android) would burn
// 0.5-1.5s of the shared main thread inside the window — exactly the CPU
// contention the rAF gate exists to prevent — while the visible result is
// identical to ~5 well-spaced frames.
const WARM_PAINT_FRAME_GAP_MS = 200;

function scheduleHostRaf(id: number, cb: FrameRequestCallback): void {
  if (!nativeRequestAnimationFrame) return;
  const scheduleNative = () => {
    if (!nativeRequestAnimationFrame) return;
    const nativeId = nativeRequestAnimationFrame((ts) => {
      nativeHostRafs.delete(id);
      if (!canRunRaf()) {
        pendingHostRafs.set(id, cb);
        return;
      }
      cb(ts);
    });

