// Warm start-screen paint: a SHORT window (not the old 2.6s snapshot-era one,
// but not zero either). Parking host-paused frames with ZERO warm frames looked
// cheaper ("the cover rides anyway"), but the first full frame — offscreen bg
// cache + full board draw + first Spine draw + GPU texture upload — is a
// pay-once cost that then lands exactly at ARRIVAL: measured 328ms (locked) /
// 174ms (second-board-v2) long tasks on A32 right under the slide, felt as a
// start stutter on every mechanic. ~1.4s at the 200ms throttle ≈ 7 frames is
// enough to absorb the first compose + decode follow-ups during the idle warm
// window instead. `?warmpaint=off` restores park-immediately for A/Bs,
// `?warmpaint=<ms>` overrides the window. Non-SWIPE targets never install this
// gate and are unaffected.
const WARM_PAINT_MS = (() => {
  if (typeof __SWIPE__ === 'undefined' || !__SWIPE__) return 0;
  try {
    if (typeof location !== 'undefined') {
      const v = new URLSearchParams(location.search).get('warmpaint');
      if (v === 'off') return 0;
      if (v && /^\d+$/.test(v)) return Math.min(4000, parseInt(v, 10));
    }
  } catch { /* noop */ }
  return 1400;
})();

