const { createServer } = require("http");
const { readFileSync, existsSync, statSync } = require("fs");
const path = require("path");
const root = path.resolve("playables");
(async () => {
  const server = createServer((req, res) => {
    const p = path.join(root, decodeURIComponent((req.url || "/").split("?")[0]));
    if (!p.startsWith(root) || !existsSync(p) || !statSync(p).isFile()) { res.statusCode = 404; res.end(); return; }
    res.setHeader("content-type", p.endsWith(".html") ? "text/html; charset=utf-8" : "application/javascript");
    res.end(readFileSync(p));
  });
  await new Promise(r => server.listen(0, "127.0.0.1", r));
  const port = server.address().port;
  const { chromium } = require("playwright");
  const browser = await chromium.launch();
  for (const id of ["merge-locked-v1-swipe", "marble-sort-swipe"]) {
    const page = await browser.newPage({ viewport: { width: 390, height: 700 } });
    await page.goto(`http://127.0.0.1:${port}/${id}/dist-swipe/index.html?hostPaused=1&auto=0`, { waitUntil: "domcontentloaded" });
    await page.waitForTimeout(2500);
    const res = await page.evaluate(() => {
      const cv = document.querySelector("canvas");
      if (!cv) return "no canvas";
      const ctx = cv.getContext("2d");
      if (!ctx) return "webgl canvas";
      const img = ctx.getImageData(0, 0, cv.width, Math.min(cv.height, 600)).data;
      const seen = new Set();
      for (let i = 0; i < img.length; i += 400) seen.add(img[i] + "," + img[i+1] + "," + img[i+2]);
      return { size: cv.width + "x" + cv.height, distinctColors: seen.size };
    });
    console.log(id, "→", JSON.stringify(res));
    await page.close();
  }
  await browser.close();
  server.close();
})().catch(e => { console.error(e); process.exit(1); });
'

