warmup() {
  // SWIPE staged-ready preparation, runs during the idle warm window while
  // the frame is still host-paused. Pre-decode the full-screen bg photo:
  // its first drawImage (screenBgCache build in the first warm-paint frame)
  // otherwise decodes the JPEG synchronously on the main thread — the
  // fattest slice of the measured ~292ms warm-frame task on A32.
  const bg = typeof bgImg.decode === 'function' ? bgImg.decode().catch(() => {}) : Promise.resolve();
  if (getQuality().useStaticSpine) return bg.then(() => undefined);
  const spine = new Promise<void>((resolve) => {
    initSpine(() => { initFinger(); resolve(); });
  });
  return Promise.all([bg, spine]).then(() => undefined);
},

