const { createServer } = require("http");
const { readFileSync, existsSync, statSync } = require("fs");
const path = require("path");
const root = path.resolve("playables");
(async () => {
  const server = createServer((req, res) => {
    const p = path.join(root, decodeURIComponent((req.url || "/").split("?")[0]));
    if (!p.startsWith(root) || !existsSync(p) || !statSync(p).isFile()) { res.statusCode = 404; res.end(); return; }
    res.setHeader("content-type", p.endsWith(".html") ? "text/html; charset=utf-8" : "application/javascript");
    res.end(readFileSync(p));
  });
  await new Promise(r => server.listen(0, "127.0.0.1", r));
  const port = server.address().port;
  const { chromium } = require("playwright");
  const browser = await chromium.launch();
  for (const id of ["merge-locked-v1-swipe", "merge-second-board-v1-swipe", "merge-second-board-v2-swipe"]) {
    const page = await browser.newPage({ viewport: { width: 390, height: 700 } });
    const errors = [];
    page.on("pageerror", e => errors.push(String(e).slice(0, 100)));
    await page.addInitScript(() => {
      window.__ev = [];
      window.addEventListener("message", (e) => { if (e.data?.source === "playable") window.__ev.push(String(e.data.type)); });
    });
    await page.goto(`http://127.0.0.1:${port}/${id}/dist-swipe/index.html?hostPaused=1&auto=0`, { waitUntil: "domcontentloaded" });
    await page.waitForTimeout(3000);
    const res = await page.evaluate(() => {
      const cv = document.querySelector("canvas");
      let paint = "no canvas";
      if (cv) { const ctx = cv.getContext("2d"); if (ctx) { const d = ctx.getImageData(0,0,cv.width,Math.min(cv.height,500)).data; const s = new Set(); for (let i=0;i<d.length;i+=400) s.add(d[i]+","+d[i+1]+","+d[i+2]); paint = s.size + " colors"; } else paint = "webgl"; }
      return { paint, events: window.__ev.filter(t => /ready/i.test(t)) };
    });
    console.log(id, "→", JSON.stringify(res), errors.length ? "ERRORS: " + errors.join(" | ") : "");
    await page.close();
  }
  await browser.close();
  server.close();
})().catch(e => { console.error(e); process.exit(1); });
'

