  for (const id of ["merge-locked-v1-swipe", "merge-second-board-v1-swipe", "merge-second-board-v2-swipe"]) {
    const page = await browser.newPage({ viewport: { width: 390, height: 700 } });
    const errors = [];
    page.on("pageerror", e => errors.push(String(e).slice(0, 120)));
    page.on("console", m => { if (m.type() === "error") errors.push(m.text().slice(0, 120)); });
    await page.addInitScript(() => {
      window.__ev = [];
      window.addEventListener("message", (e) => { if (e.data?.source === "playable") window.__ev.push(String(e.data.type)); });
    });
    await page.goto(`http://127.0.0.1:${port}/${id}/dist-swipe/index.html?hostPaused=1&auto=0`, { waitUntil: "domcontentloaded" });
    await page.waitForTimeout(1500);
    const res = await page.evaluate(async () => {
      const api = window.__playable;
      const fn = api?.swipe?.prepareInteractive ?? api?.prepareInteractive;
      const t0 = performance.now();
      try { await fn?.(); } catch (e) { return { warmup: "THREW: " + String(e).slice(0, 100) }; }
      return { warmup: fn ? `resolved in ${Math.round(performance.now() - t0)}ms` : "no hook", events: window.__ev };
    });
    console.log(id, "→", JSON.stringify(res), errors.length ? "ERRORS: " + errors.join(" | ") : "");
    await page.close();
  }
  await browser.close();
  server.close();
})().catch(e => { console.error(e); process.exit(1); });
'

