// SWIPE staged readiness lives in the existing host protocol:
// static_ready -> host prepareInteractive -> interactive_ready/ready -> activate.
// AppLovin/FTUE keep the original preloader-owned path below unchanged.
if (__SWIPE__) {
  if (hardDeadline) clearTimeout(hardDeadline);
  const SWIPE_WARMUP_CAP_MS = 5000;
  let preparePromise: Promise<void> | null = null;
  let activated = false;

  const prepareInteractive = (): Promise<void> => {
    if (preparePromise) return preparePromise;
    preparePromise = (async () => {
      const t0 = performance.now();
      if (config.warmup) {
        warmupStartedAt = Date.now();
        try {
          await Promise.race([
            config.warmup(),
            new Promise<void>((resolve) => setTimeout(resolve, SWIPE_WARMUP_CAP_MS)),
          ]);
        } catch (e) { console.warn('[bootstrap] swipe prepareInteractive failed', e); }
        warmupDone = true;
      }
      bootTimings.warmupMs = Math.round(performance.now() - t0);
      bootTimings.interactivePreparedAt = Math.round(performance.now());
      try { performance.mark('playable:interactive-prepared'); } catch { /* noop */ }
      notifyPlatform('interactive_ready');
      // Compatibility for already-deployed hosts. In the staged host this is
      // idempotent with interactive_ready; old hosts still wait for `ready`.
      notifyPlatform('ready');
      reportBootTimings('prepared');
    })();
    return preparePromise;
  };

  const activateInteractive = async () => {
    await prepareInteractive();
    if (activated) return;
    activated = true;
    const t0 = performance.now();
    try { config.onInteractive?.(); } catch (e) { console.warn('[bootstrap] onInteractive failed', e); }
    bootTimings.onInteractiveMs = Math.round(performance.now() - t0);
    bootTimings.interactiveAt = Math.round(performance.now());
    try { performance.mark('playable:interactive-done'); } catch { /* noop */ }
    reportBootTimings('interactive');
    try { trackEvent('LOADED'); } catch (e) { console.warn('[bootstrap] LOADED trackEvent failed', e); }
    gameplayReady = true;
    fireChallengeStartedIfReady();
  };

  const w = window as unknown as { __playable?: Record<string, unknown> };
  w.__playable = w.__playable || {};
  w.__playable.prepareInteractive = prepareInteractive;
  const swipeApi = w.__playable.swipe as Record<string, unknown> | undefined;
  if (swipeApi) swipeApi.prepareInteractive = prepareInteractive;
  window.addEventListener('message', (e: MessageEvent) => {
    const d = e.data as Record<string, unknown> | null;
    if (!d || d.target !== 'playable-swipe' || d.type !== 'prepareInteractive') return;
    void prepareInteractive();
  });

  // Static mount is complete, but no expensive decode/WebGL preparation has
  // been requested yet for a host-paused frame.
  notifyPlatform('static_ready');
  reportBootTimings('mounted');

  if (isHostPausedByPlatform()) {
    onFirstHostResume(() => { void activateInteractive(); });
  } else {
    // The initial/current mechanic has no intent phase. Prepare it under the
    // platform loader, activate, then let the posted ready event reveal it.
    await activateInteractive();
  }
  return;
}

// Warm up heavy first-use resources (bg video first-frame decode, audio
// buffers) UNDER the preloader, so the hitch happens off-screen and gameplay
// starts smooth. Capped so a stalled resource can't trap the preloader.
if (config.warmup) {
  const WARMUP_CAP_MS = 5000;
  warmupStartedAt = Date.now();
  try {
    await Promise.race([
      config.warmup(),
      new Promise<void>((resolve) => setTimeout(resolve, WARMUP_CAP_MS)),
    ]);
    console.log('[bootstrap] warmup done');
  } catch (e) { console.warn('[bootstrap] warmup failed', e); }
  warmupDone = true;   // snaps the progress bar to 100%
}

