let pendingInitCallback: (() => void) | null = null;
let loadedCount = 0;

function makeCharCanvas(): HTMLCanvasElement {
  const q = getQuality();
  const dpr = getDeviceDpr() * q.spineSupersample;
  const c = document.createElement('canvas');
  c.width = Math.round(CHAR_CANVAS_W * dpr);
  c.height = Math.round(CHAR_CANVAS_H * dpr);
  c.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;opacity:0;pointer-events:none;';
  document.body.appendChild(c);
  return c;
}

function initCharContext(idx: number, onLoaded: () => void): void {
  let attempt = 0;
  const tryInit = () => {
    attempt++;
    if (!spine?.webgl) {
      if (attempt < WEBGL_MAX_ATTEMPTS) { setTimeout(tryInit, WEBGL_RETRY_MS); return; }
      console.error(`[spine char ${idx}] WebGL unavailable after ${attempt} attempts`);
      return;
    }

    // Tear down any previous context at this slot (on restore-after-loss retry).
    const old = charContexts[idx];
    if (old?.glCanvas?.parentNode) old.glCanvas.parentNode.removeChild(old.glCanvas);

    const ctx: CharContext = {
      idx, glCanvas: null, sceneRenderer: null, skeleton: null, animState: null,
      lastTime: Date.now() / 1000, lastRender: 0, busyUntil: 0,
      cache: null, staticImage: null, snapshotScheduled: false,
      contextLost: false, loaded: false,
    };

    try {
      ctx.glCanvas = makeCharCanvas();
      ctx.glCanvas.addEventListener('webglcontextlost', (e) => {
        e.preventDefault();
        ctx.contextLost = true;
        ctx.loaded = false;
        console.warn(`[spine char ${idx}] webglcontextlost`);
      });
      ctx.glCanvas.addEventListener('webglcontextrestored', () => {
        console.log(`[spine char ${idx}] webglcontextrestored — reinit`);
        ctx.contextLost = false;
        attempt = 0;
        tryInit();
      });

      const managedCtx = new spine.webgl.ManagedWebGLRenderingContext(ctx.glCanvas, {
        alpha: true, premultipliedAlpha: false, preserveDrawingBuffer: false, antialias: false,
      });
      ctx.sceneRenderer = new spine.webgl.SceneRenderer(ctx.glCanvas, managedCtx, false);
      if (!ctx.sceneRenderer?.context?.gl) throw new Error('no GL context');
    } catch (e) {
      console.warn(`[spine char ${idx}] init attempt ${attempt} failed:`, e);
      if (ctx.glCanvas?.parentNode) ctx.glCanvas.parentNode.removeChild(ctx.glCanvas);
      if (attempt < WEBGL_MAX_ATTEMPTS) { setTimeout(tryInit, WEBGL_RETRY_MS); return; }
      console.error(`[spine char ${idx}] giving up after ${attempt} attempts`);
      return;
    }

    charContexts[idx] = ctx;
    loadCharAssets(ctx, onLoaded);
  };
  tryInit();
}

function loadCharAssets(ctx: CharContext, onLoaded: () => void): void {
  const data = CHAR_DATA[ctx.idx];
  const texImg = new Image();
  texImg.onload = () => {
    try {
      const glTex = new spine.webgl.GLTexture(ctx.sceneRenderer.context, texImg);
      const atlas = new spine.TextureAtlas(data.atlas, () => glTex);
      const skelJson = new spine.SkeletonJson(new spine.AtlasAttachmentLoader(atlas));
      const skelData = skelJson.readSkeletonData(data.json);
      ctx.skeleton = new spine.Skeleton(skelData);
      ctx.skeleton.setToSetupPose();
      // Emma rig override — its setup pose has realistic human proportions
      // (head ≈ 1/5 of body height). To match the chibi/cartoon style of the
      // other character slots, scale up the head bone — children (eyes, nose,
      // ears, bangs, hair) inherit position+scale and grow proportionally,
      // so the whole head reads as ~1.5–2× bigger without re-rigging.
      // Detected via the `head4` control bone, which only emma's rig has.
      // Adjust EMMA_HEAD_SCALE to tune.
      const EMMA_HEAD_SCALE = 5.5;
      const headBone = ctx.skeleton.findBone('head');
      if (headBone && ctx.skeleton.findBone('head4')) {
        headBone.scaleX = EMMA_HEAD_SCALE;
        headBone.scaleY = EMMA_HEAD_SCALE;
        ctx.skeleton.updateWorldTransform();
      }
      const stateData = new spine.AnimationStateData(skelData);
      stateData.defaultMix = 0.2;
      ctx.animState = new spine.AnimationState(stateData);
      ctx.animState.setAnimation(0, 'idle_default', true);
      ctx.loaded = true;
      onLoaded();
    } catch (e) {
      console.error(`[spine char ${ctx.idx}] asset init error:`, e);
    }
  };
  texImg.onerror = (e) => console.error(`[spine char ${ctx.idx}] tex load error:`, e);
  texImg.src = data.tex;
}

export function initSpine(callback?: () => void): void {
  pendingInitCallback = callback ?? null;
  loadedCount = 0;
  const onCharLoaded = () => {
    loadedCount++;
    if (loadedCount === CHAR_DATA.length && pendingInitCallback) {
      pendingInitCallback();
      pendingInitCallback = null;
    }
  };
  for (let i = 0; i < CHAR_DATA.length; i++) initCharContext(i, onCharLoaded);
}

// Public-API back-compat: previous version returned always true (hand-wavy "ready" flag used
// by main.ts to gate drawing). Keep the semantics so callers don't need to change.
