warmup() {
  // SWIPE staged-ready preparation, runs during the idle warm window while
  // the frame is host-paused: pre-decode every board/scene image. Their
  // first drawImage otherwise decodes synchronously inside the first
  // warm-paint frame — the bulk of the measured ~338ms warm task on A32.
  // (The door sprite sheet already decodes via createImageBitmap in mount.)
  const imgs: HTMLImageElement[] = [
    selFrameImg, generatorImg, bubbleImg, sparkleImg, iconLightImg,
    photoImg, logoImg, coinImg, tileLightImg, tileDarkImg, tileLockedImg,
    semilockedImg, ...itemImgs.slice(1), ...stoneImgs.slice(1), ...lockedImgs,
  ];
  return Promise.all(imgs.map((im) =>
    typeof im.decode === 'function' ? im.decode().catch(() => {}) : Promise.resolve(),
  )).then(() => undefined);
},
mount(container) {
  const dpr = getDeviceDpr();
  // Stash the container so mountDoorVideo can append the <video> overlay
  // into the same stacking context as the canvas/photo/sparkle layers.
  _containerRef = container;

  // Decode the door sprite sheet now, off the critical path, so it's ready by
  // the time the door break plays after the intro video.
  loadDoorSheet();

  const canvas = document.createElement('canvas');
  // Canvas + sparkleOverlay start hidden (opacity 0, scaled down) — they
  // animate in AFTER the intro video finishes. CSS transition + cubic-bezier
  // overshoot gives the soft scale-pulse the brief specifies.
  // touch-action:none — disables browser default tap/scroll/double-tap zoom
  // (Android Chrome otherwise eats a 300ms passive-event window before
  // delivering pointermove, felt as input lag on drags).
  // will-change:transform — hints the compositor to keep the canvas on its
  // own GPU layer so DOM elements painted on top (fail dialog, SDK overlays)
  // don't trigger a re-paint of the entire canvas surface every frame.
  canvas.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;display:block;touch-action:none;will-change:transform;z-index:1;opacity:0;transform:scale(0.55);transform-origin:50% 50%;transition:opacity 700ms ease-out, transform 700ms cubic-bezier(0.34, 1.56, 0.64, 1);';
  container.appendChild(canvas);
  initOverlays(container);

  // ─── Persistent store-link button (bottom-right cell) ─────────────────
  // Pulsing green CTA pill anchored to the bottom-right reserved cell.
  // Always clickable during gameplay (z-index above the canvas/photo).
  // Tap → openStore with surface=`open_store_link`. The cell-reservation
  // logic (storeBtnCellIdx + isReservedForStoreBtn) keeps game logic from
  // spawning items, accepting drops, or starting drags from this cell.
  if (!document.getElementById('playable-store-link-style')) {
    const style = document.createElement('style');
    style.id = 'playable-store-link-style';
    style.textContent = '@keyframes playable-store-link-pulse { 0%,100% { transform: scale(1); } 50% { transform: scale(1.08); } }';
    document.head.appendChild(style);
  }
  const storeBtn = document.createElement('button');
  storeBtn.id = 'playable-store-link';
  storeBtn.style.cssText = `position:fixed;background:url("${STORE_BUTTON_B64}") center/100% 100% no-repeat;background-color:transparent;border:0;padding:0;cursor:pointer;z-index:55;-webkit-tap-highlight-color:transparent;outline:none;animation:playable-store-link-pulse 1.4s ease-in-out infinite;transform-origin:center;`;
  storeBtn.addEventListener('pointerdown', (e) => {
    e.stopPropagation();
    e.preventDefault();
    openStore(getStoreUrl(config.storeUrls), { surface: 'open_store_link' });
  });
  container.appendChild(storeBtn);
  function placeStoreBtn(): void {
    // Landscape: anchored to the bottom-right cell of the merge field.
    // Portrait: anchored to the viewport's bottom-right corner outside
    // the field, vertically aligned with the generator bubble centre so
    // it reads as paired with the gameplay-bubble UI.
    const isLandscape = logW > logH;
    const sx = window.innerWidth / logW;
    const sy = window.innerHeight / logH;
    if (isLandscape) {
      const sz = cellSize;
      const pad = sz * 0.10;
      const w = Math.max(0, sz - 2 * pad);
      storeBtn.style.left = ((FIELD_PAD + (cols - 1) * sz + pad) * sx) + 'px';
      storeBtn.style.top  = ((fieldY  + (rows - 1) * sz + pad) * sy) + 'px';
      storeBtn.style.width  = (w * sx) + 'px';
      storeBtn.style.height = (w * sy) + 'px';
    } else {
      const btnPx = Math.max(48, Math.min(genBubbleR * 1.6, window.innerWidth * 0.18));
      const rightMargin = 12;
      storeBtn.style.width  = btnPx + 'px';
      storeBtn.style.height = btnPx + 'px';
      storeBtn.style.left = (window.innerWidth - btnPx - rightMargin) + 'px';
      storeBtn.style.top  = ((genBubbleY * sy) - btnPx / 2) + 'px';
    }
  }
  // photoEl + sparkleOverlay get the same treatment so the whole on-canvas
  // composition rises in together with the canvas itself.
  if (photoEl) {
    photoEl.style.transition = 'opacity 700ms ease-out, transform 700ms cubic-bezier(0.34, 1.56, 0.64, 1)';
    photoEl.style.transform = 'scale(0.55)';

