// Profile a swipe mechanic's boot: CPU-throttled headless chromium, CDP sampling
// profiler + long-task observer. Usage: node profile-mech.mjs <url> [seconds]
import { chromium } from 'playwright';

const url = process.argv[2];
const seconds = Number(process.argv[3] || 7);
if (!url) { console.error('usage: node profile-mech.mjs <url> [seconds]'); process.exit(1); }

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
const cdp = await page.context().newCDPSession(page);
await cdp.send('Emulation.setCPUThrottlingRate', { rate: 4 });
await cdp.send('Profiler.enable');
await cdp.send('Profiler.setSamplingInterval', { interval: 200 });

await page.addInitScript(() => {
  window.__longtasks = [];
  new PerformanceObserver((list) => {
    for (const e of list.getEntries()) window.__longtasks.push({ start: Math.round(e.startTime), dur: Math.round(e.duration) });
  }).observe({ type: 'longtask', buffered: true });
});

await cdp.send('Profiler.start');
await page.goto(url, { waitUntil: 'domcontentloaded' });
await page.waitForTimeout(seconds * 1000);
const { profile } = await cdp.send('Profiler.stop');
const longtasks = await page.evaluate(() => window.__longtasks);
await browser.close();

// Aggregate self time per node (sample counts x interval).
const nodeById = new Map(profile.nodes.map((n) => [n.id, n]));
const selfHits = new Map();
for (const s of profile.samples) selfHits.set(s, (selfHits.get(s) || 0) + 1);
// timeDeltas are microseconds between samples.
const totalUs = profile.timeDeltas.reduce((a, b) => a + b, 0);
const usPerSample = totalUs / profile.samples.length;

function label(n) {
  const f = n.callFrame;
  const fn = f.functionName || '(anon)';
  const file = (f.url || '').split('/').pop() || '';
  return `${fn} @ ${file}:${f.lineNumber + 1}`;
}
// Roll up: attribute self time, and also build inclusive time via parent chains.
const parentOf = new Map();
for (const n of profile.nodes) for (const c of n.children || []) parentOf.set(c, n.id);
const selfUs = new Map();
for (const [id, hits] of selfHits) selfUs.set(id, hits * usPerSample);
const inclUs = new Map();
for (const [id, us] of selfUs) {
  let cur = id;
  while (cur !== undefined) { inclUs.set(cur, (inclUs.get(cur) || 0) + us); cur = parentOf.get(cur); }
}

const rows = [...selfUs.entries()]
  .map(([id, us]) => ({ id, selfMs: us / 1000, inclMs: (inclUs.get(id) || 0) / 1000, l: label(nodeById.get(id)) }))
  .filter((r) => r.selfMs > 20)
  .sort((a, b) => b.selfMs - a.selfMs)
  .slice(0, 25);

console.log('=== long tasks (throttled 4x) ===');
for (const t of longtasks) console.log(`  at ${t.start}ms: ${t.dur}ms`);
console.log('=== top self-time functions ===');
for (const r of rows) console.log(`  self ${r.selfMs.toFixed(0)}ms incl ${r.inclMs.toFixed(0)}ms  ${r.l}`);

