export function createSfxEngine(): SfxEngine {
  let audioCtx: AudioContext | null = null;
  let masterGain: GainNode | null = null;
  let unlocked = false;
  const sources: Map<string, { dataUrl: string; volume: number }> = new Map();
  const buffers: Map<string, AudioBuffer> = new Map();
  // Looping playback bookkeeping. `pendingLoops` flags keys that should be
  // looping right now — startLoopIfReady() picks up entries once the buffer
  // is decoded + engine unlocked. `loopingSources` tracks the live
  // BufferSource per key so stopLooping can cancel cleanly.
  const pendingLoops = new Set<string>();
  const loopingSources = new Map<string, AudioBufferSourceNode>();

  /** Decode a `data:audio/...;base64,...` URI to PCM bytes. Used for the
   *  prod build path where Vite's `?inline` produces base64 data URIs. The
   *  cleanup pipeline (URL-decode %XX → strip whitespace → URL-safe base64
   *  → pad to multiple of 4) makes atob() resilient to encoder quirks
   *  observed across Vite versions. */
  function dataUrlToArrayBuffer(dataUrl: string): ArrayBuffer {
    const comma = dataUrl.indexOf(',');
    let b64 = comma >= 0 ? dataUrl.slice(comma + 1) : dataUrl;
    if (b64.indexOf('%') >= 0) {
      try { b64 = decodeURIComponent(b64); } catch { /* keep original */ }
    }
    b64 = b64.replace(/\s+/g, '').replace(/-/g, '+').replace(/_/g, '/');
    while (b64.length % 4 !== 0) b64 += '=';
    const bin = atob(b64);
    const buf = new ArrayBuffer(bin.length);
    const view = new Uint8Array(buf);
    for (let i = 0; i < bin.length; i++) view[i] = bin.charCodeAt(i);
    return buf;
  }

  // Eager AudioContext creation. Some iOS WKWebView builds want the context
  // to EXIST at gesture-time so that resume() inside the gesture flips it to
  // 'running' — lazy creation inside the gesture sometimes silently fails.
  if (typeof window !== 'undefined') {
    try {
      const Ctor = (window as any).AudioContext || (window as any).webkitAudioContext;
      if (Ctor) {
        audioCtx = new Ctor();
        masterGain = audioCtx!.createGain();
        masterGain.gain.value = 1;
        masterGain.connect(audioCtx!.destination);
        audioCtx!.addEventListener('statechange', () => {
          if (audioCtx && audioCtx.state !== 'running' && unlocked) {
            audioCtx.resume().catch(() => {});
          }
        });
      }
    } catch { /* ignore — engine no-ops without ctx */ }
  }

  function startLoopIfReady(key: string): void {
    if (!pendingLoops.has(key)) return;
    if (loopingSources.has(key)) return;
    if (!audioCtx || !masterGain || !unlocked) return;
    const buf = buffers.get(key);
    if (!buf) return;
    const src = sources.get(key);
    try {
      const node = audioCtx.createBufferSource();
      node.buffer = buf;
      node.loop = true;
      const g = audioCtx.createGain();
      g.gain.value = src ? src.volume : 1;
      node.connect(g);
      g.connect(masterGain);
      node.start();
      loopingSources.set(key, node);
    } catch (e) {
      if (typeof console !== 'undefined') console.warn('[sfx] startLooping threw — ' + key + ': ' + String(e));
    }
  }

  const decodeErrors: string[] = [];
  const inflight = new Set<string>();
