const DOOR_SHEET_CELL = 256;   // px per frame in the sheet
let doorVideoEl: HTMLCanvasElement | null = null;
let doorCtx: CanvasRenderingContext2D | null = null;
let doorSheet: ImageBitmap | HTMLImageElement | null = null;
let doorSheetReady = false;
let doorAnimStartT = 0;        // Date.now() when the break started (frame 0)
let doorLastFrame = -1;        // last blitted frame index (skip redundant blits)

// Decode the sheet ONCE, early (called from mount so it's ready before the door
// appears after the intro video).
function loadDoorSheet(): void {
  if (doorSheet || doorSheetReady) return;
  const img = new Image();
  img.decoding = 'async';
  img.onload = () => {
    if (typeof createImageBitmap === 'function') {
      createImageBitmap(img).then((bm) => { doorSheet = bm; doorSheetReady = true; doorLastFrame = -1; })
        .catch(() => { doorSheet = img; doorSheetReady = true; doorLastFrame = -1; });
    } else { doorSheet = img; doorSheetReady = true; doorLastFrame = -1; }
  };
  img.src = DOOR_SHEET_URL;
}

// Visual tuning: door occupies a slightly smaller box than the raw door-rect
// (the 2×2 top-left cells). Reduces the "too tall" feel and gives the HP-bar a
// small gap above the art.
const DOOR_VIDEO_SCALE = 0.984;   // bumped 20% (was 0.82) — bottom-anchored grow keeps the bar contact point
function placeDoorVideo(): void {
  if (!doorVideoEl) return;
