const engine: SfxEngine = {
  register(key, dataUrl, volume) {
    sources.set(key, { dataUrl, volume });
    // Decode eagerly at load — NOT only after unlock. decodeAudioData works on
    // a suspended AudioContext (no user gesture needed), so the PCM is ready by
    // the time the first tap unlocks playback. Without this, the first gesture
    // kicks off decoding of every buffer at once and heavy clips (e.g. a long
    // music loop) start audibly late. decodeAll() skips already-decoded/inflight
    // keys, so calling it per-register is cheap.
    decodeAll();
  },
  unlock() {
    if (!audioCtx || !masterGain) return;
    // Resume the AudioContext inside the user gesture. iOS WKWebView wants
    // both the resume AND a tickle BufferSource to start during the
    // gesture, otherwise the context can stay 'suspended' silently.
    // No silent-loop session-promotion trick — we WANT Web Audio to inherit
    // the page-level 'ambient' session category so the ringer-silent switch
    // mutes the entire creative, matching the behaviour of competitor ads.
    if (audioCtx.state !== 'running' && audioCtx.state !== 'closed') {
      audioCtx.resume().catch(() => {});
    }
    try {
      const sb = audioCtx.createBuffer(1, 1, 22050);
      const src = audioCtx.createBufferSource();
      src.buffer = sb;
      src.connect(audioCtx.destination);
      src.start(0);
    } catch { /* ignore */ }
    unlocked = true;
    decodeAll();
    // Any loop pending from a `playLooping` called before unlock now starts.
    for (const key of pendingLoops) startLoopIfReady(key);
  },
  mute() {
    if (masterGain) masterGain.gain.value = 0;
  },
  unmute() {
    if (unlocked && masterGain) masterGain.gain.value = 1;
  },
  play(key) {
    if (!audioCtx || !masterGain) return;
    const buf = buffers.get(key);
    if (!buf) return; // not yet decoded — drop silently
    const src = sources.get(key);
    try {
      const node = audioCtx.createBufferSource();
      node.buffer = buf;
      const g = audioCtx.createGain();
      g.gain.value = src ? src.volume : 1;
      node.connect(g);
      g.connect(masterGain);
      node.start();
    } catch { /* ignore */ }
  },
  playFrom(key, offsetSec) {
    if (!audioCtx || !masterGain) return null;
    const buf = buffers.get(key);
    if (!buf) return null;
    const src = sources.get(key);
    const safeOffset = Math.max(0, Math.min(offsetSec, Math.max(0, buf.duration - 0.01)));
    try {
      const node = audioCtx.createBufferSource();
      node.buffer = buf;
      const g = audioCtx.createGain();
      g.gain.value = src ? src.volume : 1;
      node.connect(g);
      g.connect(masterGain);
      let stopped = false;
      node.onended = () => {
        stopped = true;
        try { node.disconnect(); } catch { /* ignore */ }
        try { g.disconnect(); } catch { /* ignore */ }
      };
      node.start(0, safeOffset);
      return () => {
        if (stopped) return;
        stopped = true;
        try { node.stop(); } catch { /* already stopped */ }

