const decodeErrors: string[] = [];
const inflight = new Set<string>();
const failed = new Set<string>();
let decodePumpScheduled = false;

function recordFailure(key: string, e: unknown, what: string): void {
  const msg = key + ': ' + String(e);
  decodeErrors.push(msg);
  failed.add(key);
  if (typeof console !== 'undefined') console.warn('[sfx] ' + what + ' — ' + msg);
}

function hasPendingDecode(): boolean {
  for (const [key, src] of sources) {
    if (buffers.has(key) || inflight.has(key) || failed.has(key)) continue;
    if (src.dataUrl.indexOf('data:') === 0 || import.meta.env.DEV) return true;
  }
  return false;
}

// Decode pump: ONE data-URI clip per macrotask. The synchronous atob→byte
// copy of a clip is tens of ms; registering ~8 clips at module scope used to
// run them all inside the payload-eval task — a 150-250ms main-thread block.
// On SWIPE that block lands while THIS mechanic warms in the background and
// janks the mechanic the user is playing. Slicing keeps every task small;
// the PCM is still ready long before the first gesture unlocks playback.
function decodeStep(): void {
  decodePumpScheduled = false;
  if (!audioCtx) return;
  for (const [key, src] of sources) {
    if (buffers.has(key) || inflight.has(key) || failed.has(key)) continue;
    // Two paths chosen by source shape:
    //   - `data:audio/...` URI (prod build) → synchronous atob → decode.
    //   - URL path like `/assets/foo.mp3` (dev preview only) → fetch +
    //     async decode. The dev path is gated on `import.meta.env.DEV` so
    //     it tree-shakes out of the prod bundle — the AppLovin static
    //     scanner forbids `fetch(` in single-file ads, and we want a clean
    //     prod output regardless of whether any source happens to be a
    //     URL at runtime.
    if (src.dataUrl.indexOf('data:') === 0) {
      inflight.add(key);
      try {
        const ab = dataUrlToArrayBuffer(src.dataUrl);
        audioCtx.decodeAudioData(ab,
          (buf) => { buffers.set(key, buf); inflight.delete(key); startLoopIfReady(key); },
          (e) => { inflight.delete(key); recordFailure(key, e, 'decodeAudioData rejected'); },
        );
      } catch (e) {
        inflight.delete(key);
        recordFailure(key, e, 'dataUrl parse failed');
      }
      break;   // one synchronous atob per task — the rest pump on later ticks
    } else if (import.meta.env.DEV) {
      inflight.add(key);
      fetch(src.dataUrl).then((r) => {
        if (!r.ok) throw new Error('fetch failed: ' + r.status);
        return r.arrayBuffer();
      }).then((ab) => {
        if (!audioCtx) return;
        audioCtx.decodeAudioData(ab,
          (buf) => { buffers.set(key, buf); inflight.delete(key); startLoopIfReady(key); },
          (e) => { inflight.delete(key); recordFailure(key, e, 'decodeAudioData rejected'); },
        );
      }).catch((e) => {
        inflight.delete(key);
        recordFailure(key, e, 'fetch failed');
      });
    }
  }
  if (hasPendingDecode()) decodeAll();
}

function decodeAll(): void {
  if (!audioCtx || decodePumpScheduled) return;
  decodePumpScheduled = true;
  setTimeout(decodeStep, 0);
}

