input.new_string:
export function initSpine(callback?: () => void, staggered = false): void {
  pendingInitCallback = callback ?? null;
  loadedCount = 0;
  const onCharLoaded = () => {
    loadedCount++;
    if (loadedCount === CHAR_DATA.length && pendingInitCallback) {
      pendingInitCallback();
      pendingInitCallback = null;
    }
  };
  if (!staggered) {
    for (let i = 0; i < CHAR_DATA.length; i++) initCharContext(i, onCharLoaded);
    return;
  }
  // Staggered: one char per step with a breather between. Each char costs two
  // main-thread chunks (GL context + shader compile, then texture upload +
  // skeleton parse) — running all three chars in one tick is a 300-600ms task.
  // Used when spine comes up AFTER the frame is already visible: small spaced
  // chunks instead of one freeze. A char that never loads (WebGL give-up)
  // must not stall the chain — the timeout guard advances it regardless; the
  // prerendered composite keeps standing in for that char.
  let next = 0;
  const STAGGER_MS = 150;
  const startNext = () => {
    if (next >= CHAR_DATA.length) return;
    const i = next++;
    let advanced = false;
    const advance = () => {
      if (advanced) return;
      advanced = true;
      setTimeout(startNext, STAGGER_MS);
    };
    initCharContext(i, () => { onCharLoaded(); advance(); });
    setTimeout(advance, 2000);
  };
  startNext();
}

