function loadDoorSheet(): void {
  if (doorSheet || doorSheetReady) return;
  const img = new Image();
  img.decoding = 'async';
  img.onload = () => {
    // Rasterize on the image-decode pool FIRST: createImageBitmap(img) on a
    // not-yet-decoded image does the full sheet decode synchronously on the
    // main thread (profiled ~250ms@4x CPU throttle — the fattest single block
    // of this mechanic's warm). After decode() the bitmap step is a cheap copy.
    const toBitmap = () => {
      if (typeof createImageBitmap === 'function') {
        createImageBitmap(img).then((bm) => { doorSheet = bm; doorSheetReady = true; doorLastFrame = -1; })
          .catch(() => { doorSheet = img; doorSheetReady = true; doorLastFrame = -1; });
      } else { doorSheet = img; doorSheetReady = true; doorLastFrame = -1; }
    };
    if (typeof img.decode === 'function') img.decode().then(toBitmap, toBitmap);
    else toBitmap();
  };
  img.src = DOOR_SHEET_URL;
}

