function loadDoorSheet(): void {
  if (doorSheet || doorSheetReady) return;
  const done = (sheet: ImageBitmap | HTMLImageElement) => {
    doorSheet = sheet; doorSheetReady = true; doorLastFrame = -1;
  };
  const viaImg = () => {
    const img = new Image();
    img.decoding = 'async';
    img.onload = () => done(img);
    img.src = DOOR_SHEET_URL;
  };
  // Blob → createImageBitmap decodes the sheet entirely on the worker pool.
  // createImageBitmap(HTMLImageElement) — even after img.decode() — still
  // rasterized the whole sheet synchronously on the main thread (profiled
  // ~240ms@4x CPU throttle, the fattest single block of this mechanic's
  // warm). Same fetch(dataUrl) pattern pins-swipe already ships.
  if (typeof createImageBitmap === 'function' && typeof fetch === 'function') {
    fetch(DOOR_SHEET_URL)
      .then((r) => r.blob())
      .then((b) => createImageBitmap(b))
      .then((bm) => done(bm))
      .catch(viaImg);
  } else viaImg();
}

