    this.settlingTargetIndex = null;
  } else {
    this.settlingTargetIndex = null;
    this.liveHold.clear();
    this.updateLive();
    this.applyActiveStates();
    this.pumpPrefetchQueue();
  }
  // resume/pause happens on the transitionend (= after the slide)
}

