toolUseResult.originalFile:
// Verify the finger-aware warm gate with REAL touch input (CDP):
// as soon as #0 reveals, tap (manual takeover — veil lifts) and HOLD a finger
// inside the mechanic. The warm of #1 reaches static_ready under the held
// finger → prepareInteractive must defer, then flush on release.
import { createRequire } from 'module';
const require = createRequire('/Users/gleb/My projects/p4g-platform-workspace/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
const page = await ctx.newPage();
const logs = [];
let revealedResolve;
const revealed = new Promise((r) => { revealedResolve = r; });
page.on('console', (m) => {
  const t = m.text();
  if (t.includes('[warm') || t.includes('[probe-test]')) logs.push(t);
  if (t.includes('#0 revealed')) revealedResolve();
});
await page.addInitScript(() => {
  const tag = () => (window === window.top ? 'TOP' : location.pathname.split('/').pop());
  window.addEventListener('pointerdown', (e) => {
    const el = e.target && e.target.className;
    console.log('[probe-test] pd @' + tag() + ' trusted=' + e.isTrusted + ' target=' + String(el).slice(0, 40));
  }, { capture: true });
  window.addEventListener('pointerup', () => console.log('[probe-test] pu @' + tag()), { capture: true });
});

const cdp = await page.context().newCDPSession(page);
const touch = (type, points) => cdp.send('Input.dispatchTouchEvent', { type, touchPoints: points });

await page.goto('http://localhost:5199/?warm=1&takeover=continue', { waitUntil: 'domcontentloaded' });
await Promise.race([revealed, page.waitForTimeout(6000)]);
// The PLATFORM boot preloader swallows all input — wait until it's gone.
await page.waitForFunction(() => !document.querySelector('.preloader'), null, { timeout: 15000 }).catch(() => {});
await page.waitForTimeout(300);
// Swipe to #1 → its settle schedules the warm of #2.
await touch('touchStart', [{ x: 195, y: 620, id: 1 }]);
for (let y = 620; y >= 220; y -= 50) { await touch('touchMove', [{ x: 195, y, id: 1 }]); await page.waitForTimeout(16); }
await touch('touchEnd', []);
await page.waitForTimeout(700);    // settle + reveal of #1
// Tap → manual takeover (veil lifts; touches go into the iframe).
await touch('touchStart', [{ x: 195, y: 420, id: 1 }]);
await page.waitForTimeout(35);
await touch('touchEnd', []);
await page.waitForTimeout(80);
// Hold INSIDE the mechanic through the warm window of #2.
await touch('touchStart', [{ x: 195, y: 420, id: 1 }]);
await page.waitForTimeout(5000);
await touch('touchEnd', []);
await page.waitForTimeout(2500);   // release → flush → prepare #2
let snap = null;
try { snap = await page.evaluate(() => (window.__feedWarm ? window.__feedWarm() : null)); } catch { /* noop */ }
await browser.close();

console.log('--- warm log ---');
for (const l of logs) console.log(l);
console.log('deferred lines:', logs.filter((l) => l.includes('deferred')).length);
if (snap) console.log('--- snapshot ---\n' + JSON.stringify(snap).slice(0, 700));

