  warmup() {
    // SWIPE staged-ready preparation, runs during the idle warm window while
    // the frame is still host-paused. Pre-decode the full-screen bg photo so
    // its first drawImage doesn't decode the JPEG synchronously on the main
    // thread inside the first warm-paint frame.
    const bg = typeof bgImg.decode === 'function' ? bgImg.decode().catch(() => {}) : Promise.resolve();
    // SWIPE: NO spine here — warm-phase main-thread blocks jank the mechanic
    // the user is CURRENTLY playing (all feed iframes share one thread).
    // Live Spine comes up after arrival instead — see onInteractive below.
    if (__SWIPE__) return bg.then(() => undefined);
    if (getQuality().useStaticSpine) return bg.then(() => undefined);
    const spine = new Promise<void>((resolve) => {
      initSpine(() => { initFinger(); resolve(); });
    });
    return Promise.all([bg, spine]).then(() => undefined);
  },
  onInteractive() {
    // SWIPE: the frame just became visible-and-running (arrival, behind the
    // cover fade). The prerendered composite is on screen for the characters;
    // bring live Spine up STAGGERED — one char per spaced step — so no single
    // chunk freezes gameplay. 700ms lets the arrival fade + first paints pass.
    if (!__SWIPE__ || getQuality().useStaticSpine) return;
    window.setTimeout(() => {
      initSpine(() => initFinger(), true);
      // A char that never loads keeps the all-loaded callback from firing —
      // don't let that strand the tutor hand.
      window.setTimeout(() => { if (!isFingerReady()) initFinger(); }, 8000);
    }, 700);
  },
});

