import { createRequire } from 'module';
const require = createRequire('/Users/gleb/My projects/p4g-platform-workspace/package.json');
const { chromium } = require('playwright');

const IDS = [
  'marble-sort-swipe', 'merge-locked-v1-swipe', 'merge-second-board-v1-swipe',
  'merge-second-board-v2-swipe', 'merge-timepress-no-orders-v1-swipe',
  'merge-timepress-v1-swipe', 'merge-timepress-v2-swipe', 'pins-swipe',
  'pins-v1-swipe', 'short-drama-swipe',
];
const browser = await chromium.launch();
for (const id of IDS) {
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e).slice(0, 120)));
  page.on('console', (m) => {
    if (m.type() !== 'error') return;
    const t = m.text();
    if (/webgl|WebGL|VERTEX_SHADER|spine char|gl context/i.test(t)) return; // headless GL limits
    errors.push(t.slice(0, 120));
  });
  try {
    await page.goto(`http://localhost:5199/${id}.html?auto=0`, { waitUntil: 'domcontentloaded', timeout: 15000 });
    const prepared = await page.evaluate(async () => {
      const p = window.__playable;
      if (!p || typeof p.prepareInteractive !== 'function') return 'no-api';
      const r = await Promise.race([
        Promise.resolve(p.prepareInteractive()).then(() => 'ok'),
        new Promise((res) => setTimeout(() => res('timeout'), 9000)),
      ]);
      return r;
    });
    await page.waitForTimeout(400);
    const hasCanvas = await page.evaluate(() => !!document.querySelector('canvas'));
    console.log(`${id}: prepare=${prepared} canvas=${hasCanvas} errors=${errors.length}${errors.length ? ' | ' + errors[0] : ''}`);
  } catch (e) {
    console.log(`${id}: LOAD FAIL ${String(e).slice(0, 100)}`);
  }
  await page.close();
}
await browser.close();

