// ─── Composite cache (for prerender capture + composite fallback) ─────────

let compositeCache: HTMLCanvasElement | null = null;
function updateCompositeCache(logW: number, logH: number,
                              positions: { charIdx: number; x: number; y: number; scale: number; alpha?: number }[]): void {
  // Renders the current per-char caches onto a single full-scene 2D canvas at their game
  // positions. Used by prerender-spine.mjs (via getSpineCacheDataUrl) to bake a composite
  // fallback PNG. Not used on runtime hot path — per-char blits go straight to main ctx.
  const dpr = getDeviceDpr();
  const stripHeight = Math.round(logH * 0.7);
  const w = Math.round(logW * dpr);
  const h = Math.round(stripHeight * dpr);
  if (!compositeCache || compositeCache.width !== w || compositeCache.height !== h) {
    compositeCache = document.createElement('canvas');
    compositeCache.width = w; compositeCache.height = h;
  }
  const cctx = compositeCache.getContext('2d')!;
  cctx.clearRect(0, 0, w, h);
  cctx.save();
  cctx.scale(dpr, dpr);
  for (const pos of positions) {
    const c = charContexts[pos.charIdx];
    if (!c?.cache) continue;
    blitCharCache(cctx as any, c, pos);
  }
  cctx.restore();
}

export function drawAllSpine(
  mainCtx: CanvasRenderingContext2D,
  positions: { charIdx: number; x: number; y: number; scale: number; alpha?: number }[],
  logW: number, logH: number
): void {
  const now = Date.now();
  const spineFps = getQuality().spineFps;
  let anyRendered = false;

  // No-WebGL fallback: when zero char contexts exist (WebGL never came up — broken device,
  // or no-WebGL test path), the composite prerendered PNG stands in for the whole character
  // layer. Single blit covers all 3 slots at their baked positions.
  const noCharCtxInitialized = !charContexts.some(c => c !== null);
  if (noCharCtxInitialized && spinePrerenderedImage && positions.length > 0) {
    mainCtx.drawImage(spinePrerenderedImage, 0, 0, logW, Math.round(logH * 0.7));
    if (typeof window !== 'undefined') {
      const w = window as any; w.__playable = w.__playable || {};
      w.__playable._spineStaticFallbackCalls = (w.__playable._spineStaticFallbackCalls || 0) + 1;
      w.__playable._spineStaticSource = 'prerendered';
    }
    return;
  }

  for (const pos of positions) {
    const c = charContexts[pos.charIdx];
    if (!c) continue;

    // No-WebGL fallback for this char specifically. Falls through to shared prerendered PNG
    // blit if we can't get per-char art (runtime snapshot, gpu cache).
    if (!c.loaded || c.contextLost || !c.sceneRenderer || !c.glCanvas) {
      const staticSource: HTMLImageElement | HTMLCanvasElement | null = c.staticImage || c.cache;
      if (staticSource) {
        blitCharFallback(mainCtx, staticSource, pos);
        if (typeof window !== 'undefined') {
          const w = window as any; w.__playable = w.__playable || {};
          w.__playable._spineStaticFallbackCalls = (w.__playable._spineStaticFallbackCalls || 0) + 1;
          w.__playable._spineStaticSource = c.staticImage ? 'runtime-snapshot' : 'gpu-cache';
        }

