const now = Date.now();
const spineFps = getQuality().spineFps;
let anyRendered = false;

// No-WebGL fallback: when zero char contexts exist (WebGL never came up — broken device,
// or ?nowebgl=1 dev preview), blit each character's prerendered PNG at its runtime slot
// position using the same blitCharFallback geometry as the WebGL path. This makes chars
// follow the live order layout in portrait AND landscape without baking position into art.
const noCharCtxInitialized = !charContexts.some(c => c !== null);
if (noCharCtxInitialized && positions.length > 0) {
  const havePerChar = charPrerenderedImages.some(img => img !== null);
  if (havePerChar) {
    for (const pos of positions) {
      const img = charPrerenderedImages[pos.charIdx];
      if (!img) continue;
      blitCharFallback(mainCtx, img, pos);
    }
    if (typeof window !== 'undefined') {
      const w = window as any; w.__playable = w.__playable || {};
      w.__playable._spineStaticFallbackCalls = (w.__playable._spineStaticFallbackCalls || 0) + 1;
      w.__playable._spineStaticSource = 'per-char-prerendered';
    }
    return;
  }
  // Legacy fallback: composite PNG only. AR-fit into strip — positions will not align
  // perfectly with landscape slots, but nothing will be invisible. Goes away once prerender
  // re-runs with per-char support.
  if (spinePrerenderedImage) {
    const srcW = spinePrerenderedImage.naturalWidth || 390;
    const srcH = spinePrerenderedImage.naturalHeight || 844;
    const stripH = Math.round(logH * 0.7);
    const srcAR = srcW / srcH;
    const dstAR = logW / stripH;
    let dw: number, dh: number, dx: number, dy: number;
    if (dstAR > srcAR) {
      dh = stripH; dw = stripH * srcAR;
      dx = (logW - dw) / 2; dy = 0;
    } else {
      dw = logW; dh = logW / srcAR;
      dx = 0; dy = 0;
    }
    mainCtx.drawImage(spinePrerenderedImage, dx, dy, dw, dh);
    if (typeof window !== 'undefined') {
      const w = window as any; w.__playable = w.__playable || {};
      w.__playable._spineStaticFallbackCalls = (w.__playable._spineStaticFallbackCalls || 0) + 1;

