  for (const pos of positions) {
    const c = charContexts[pos.charIdx];
    if (!c) continue;

    // No-WebGL fallback for this char specifically. Falls through to shared prerendered PNG
    // blit if we can't get per-char art (runtime snapshot, gpu cache).
    if (!c.loaded || c.contextLost || !c.sceneRenderer || !c.glCanvas) {
      const staticSource: HTMLImageElement | HTMLCanvasElement | null = c.staticImage || c.cache;
      if (staticSource) {
        blitCharFallback(mainCtx, staticSource, pos);
        if (typeof window !== 'undefined') {
          const w = window as any; w.__playable = w.__playable || {};
          w.__playable._spineStaticFallbackCalls = (w.__playable._spineStaticFallbackCalls || 0) + 1;
          w.__playable._spineStaticSource = c.staticImage ? 'runtime-snapshot' : 'gpu-cache';
        }
      } else if (spinePrerenderedImage) {
        // Composite prerendered PNG has all 3 chars baked at their slot positions. We can't
        // cleanly slice one char out, so just blit it whole for this char's position request.
        // This path only fires when NO per-char WebGL survived — rare, acceptable visual.
        mainCtx.drawImage(spinePrerenderedImage, 0, 0, logW, Math.round(logH * 0.7));
        if (typeof window !== 'undefined') {
          const w = window as any; w.__playable = w.__playable || {};
          w.__playable._spineStaticFallbackCalls = (w.__playable._spineStaticFallbackCalls || 0) + 1;
          w.__playable._spineStaticSource = 'prerendered';
        }
      }
      continue;
    }

    // Throttle per-char — each context has its own timer. Full spineFps inside its busy
    // window, same rate outside for now. Future: could drop to idle rate when !busy.
    if (now - c.lastRender >= spineFps) {
      renderCharToCache(c);
      c.lastRender = now;
      anyRendered = true;
    }
    if (c.cache) blitCharCache(mainCtx, c, pos);
  }

  // Maintain composite for prerender access. Only rebuild when at least one char just
  // rendered this frame (saves work on frames where we're only blitting cached content).
  if (anyRendered) updateCompositeCache(logW, logH, positions);
}

