1	/**
2	 * Telegram Mini App integration.
3	 *
4	 * No-ops entirely outside Telegram (normal browser, AppLovin webview, Render
5	 * preview) — there the CSS `env(safe-area-inset-*)` fallbacks apply as before.
6	 *
7	 * Inside Telegram it:
8	 *   - ready() + expand()                          — standard handshake.
9	 *   - requestFullscreen() (Bot API 8.0)           — edge-to-edge UNDER the notch.
10	 *   - disableVerticalSwipes() (Bot API 7.7+)      — CRITICAL: the feed pages
11	 *       vertically, and Telegram's own swipe-down-to-minimise would otherwise
12	 *       fight (and steal) every upward swipe.
13	 *   - mirrors Telegram's safe-area insets into the `--safe-*` CSS vars, because
14	 *       in fullscreen `env(safe-area-inset-*)` is NOT populated — Telegram
15	 *       exposes the device inset (`safeAreaInset`) AND its own header inset
16	 *       (`contentSafeAreaInset`); we sum them so feed chrome clears both.
17	 */
18	
19	type AnyTG = any;
20	
21	/** Raw Telegram initData for the `Authorization: tma <initData>` header. Null
22	 *  outside Telegram (normal browser / AppLovin) — callers then no-op the social
23	 *  features. `?initData=` query override is a DEV convenience for testing the
24	 *  backend from a plain browser. */
25	export function getInitData(): string | null {
26	  try {
27	    const d = (window as any).Telegram?.WebApp?.initData;
28	    if (typeof d === 'string' && d.length > 0) return d;
29	    const q = new URLSearchParams(location.search).get('initData');
30	    return q && q.length > 0 ? q : null;
31	  } catch {
32	    return null;
33	  }
34	}
35	
36	/** Telegram launch start_param (deep-link payload), e.g. a challenge id. Null
37	 *  outside Telegram. Tags session entry source (direct|challenge|referral). */
38	export function getStartParam(): string | null {
39	  try {
40	    const p = (window as any).Telegram?.WebApp?.initDataUnsafe?.start_param;
41	    return typeof p === 'string' && p.length > 0 ? p : null;
42	  } catch {
43	    return null;
44	  }
45	}
46	
47	/** A challenge deep-link start_param is a plain uuid (with or without dashes). */
