const req = createRequire('/Users/gleb/My projects/p4g-platform-workspace/package.json');
const { chromium } = req('playwright');
(async () => {
  const browser = await chromium.launch();
  // 1) Feed: during cold load the current .game must carry BOTH game--loading
  //    and game--autoplay (slot pre-scaled), and keep autoplay after reveal.
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await page.goto('http://localhost:5199/', { waitUntil: 'domcontentloaded' });
  const samples = [];
  for (let t = 0; t < 4000; t += 200) {
    const s = await page.evaluate(() => {
      const g = document.querySelector('.page--in-viewport .game') || document.querySelector('.game');
      if (!g) return null;
      return { loading: g.classList.contains('game--loading'), auto: g.classList.contains('game--autoplay') };
    });
    if (s) samples.push(s);
    await page.waitForTimeout(200);
  }
  const loadingSamples = samples.filter((s) => s.loading);
  const preScaled = loadingSamples.length > 0 && loadingSamples.every((s) => s.auto);
  console.log('feed cold-load: loadingSamples=' + loadingSamples.length + ' allPreScaled=' + preScaled + ' finalAuto=' + (samples[samples.length-1]||{}).auto);
  await page.close();
  // 2) locked: during staggered init nothing drawn (no fallback calls), no errors.
  const p2 = await browser.newPage({ viewport: { width: 390, height: 844 } });
  const errs = [];
  p2.on('pageerror', (e) => errs.push(String(e).slice(0, 80)));
  await p2.goto('http://localhost:5199/merge-locked-v1-swipe.html?auto=0', { waitUntil: 'domcontentloaded' });
  await p2.waitForTimeout(4000);
  const st = await p2.evaluate(() => {
    const p = window.__playable || {};
    return { fallbackCalls: p._spineStaticFallbackCalls || 0, canvas: !!document.querySelector('canvas') };
  });
  console.log('locked hidden-init:', JSON.stringify(st), 'errors=' + errs.length);
  await browser.close();
})();
