1	#!/usr/bin/env node
2	/**
3	 * Local-only T3 experiment worker.
4	 *
5	 * Claude Code or Codex may edit only marble-sort-swipe/src inside a disposable
6	 * clone pinned to an exact commit/tree. The release checkout and its refs are
7	 * never writable by the agent. This process validates the diff, builds with the
8	 * known toolchain, and requires a complete headless autoplay WIN before exposing
9	 * an artifact under the ignored u/local-experiments directory.
10	 */
11	import { spawn } from 'child_process';
12	import { createHash } from 'crypto';
