32	const playablesRoot = process.env.PLAYABLES_ROOT
33	  ? path.resolve(process.env.PLAYABLES_ROOT)
34	  : path.join(workspace, 'playables');
35	const localRoot = path.join(repoRoot, '.local-experiments');
36	const artifactRoot = path.join(repoRoot, 'u', 'local-experiments');
37	const baselineCatalog = JSON.parse(readFileSync(path.join(repoRoot, 'generator', 'baselines.json'), 'utf8'));
38	const MAX_ATTEMPTS = Math.max(1, Math.min(3, Number(process.env.UGC_EXPERIMENT_ATTEMPTS || 3)));
39	const AGENT_TIMEOUT_MS = Math.max(60, Number(process.env.UGC_EXPERIMENT_AGENT_TIMEOUT_SEC || 600)) * 1000;
40	const TEST_TIMEOUT_MS = Math.max(30, Number(process.env.UGC_EXPERIMENT_TEST_TIMEOUT_SEC || 150)) * 1000;
41	const CLAUDE_MODEL = process.env.ISLAND_EXPERIMENT_MODEL || 'sonnet';
42	const CODEX_MODEL = String(process.env.CODEX_EXPERIMENT_MODEL || '').trim();
43	const EFFORT = new Set(['low', 'medium', 'high', 'xhigh']).has(process.env.ISLAND_EXPERIMENT_EFFORT || '')
44	  ? process.env.ISLAND_EXPERIMENT_EFFORT
45	  : 'medium';
46	
47	function subscriptionCliEnv(provider) {
48	  const env = { ...process.env };
49	  const keys = provider === 'codex'
50	    ? ['OPENAI_API_KEY', 'OPENAI_BASE_URL', 'AZURE_OPENAI_API_KEY', 'CODEX_API_KEY']
51	    : ['ANTHROPIC_API_KEY', 'ANTHROPIC_AUTH_TOKEN', 'ANTHROPIC_BASE_URL', 'CLAUDE_CODE_USE_BEDROCK', 'CLAUDE_CODE_USE_VERTEX', 'CLAUDE_CODE_USE_FOUNDRY'];
52	  for (const key of keys) delete env[key];
53	  return env;
54	}
55	
56	const args = {};
57	for (let i = 2; i < process.argv.length; i += 2) args[process.argv[i].replace(/^--/, '')] = process.argv[i + 1];
58	const prompt = String(args.prompt || '').trim().slice(0, 500);
59	const feedback = String(args.feedback || '').trim().slice(0, 500);
60	const parentId = String(args.parent || '').trim();
61	const provider = args.provider === 'codex' ? 'codex' : 'claude';
62	const baselineId = String(args.baseline || 'sort-v2').trim();
63	const baseline = baselineCatalog.baselines?.[baselineId];
64	if (!baseline || baseline.template !== 'sort' || baseline.releasePlayable !== false) {
65	  fail(`unknown or unsafe generator baseline: ${baselineId}`);
66	}
67	let concept;
68	try { concept = JSON.parse(String(args.concept || '{}')); } catch { concept = {}; }
69	const title = String(concept.title || 'Wild sort experiment').trim().slice(0, 60);
70	const pitch = String(concept.pitch || concept.summary || '').trim().slice(0, 500);
71	const mechanic = String(concept.mechanic || '').trim().slice(0, 500);
72	const feeling = String(concept.feeling || '').trim().slice(0, 240);
73	
74	function status(phase, message, attempt = 0) {
75	  console.log(`STATUS ${JSON.stringify({ phase, message, attempt })}`);
76	}
77	
78	function fail(message) {
79	  throw new Error(String(message).replace(/\s+/g, ' ').trim().slice(0, 5000));
80	}
81	
82	class AutoplayIncompleteError extends Error {}
83	
84	function run(command, commandArgs, options = {}) {
85	  return new Promise((resolve, reject) => {
86	    const child = spawn(command, commandArgs, {
87	      cwd: options.cwd,
88	      env: options.replaceEnv ? options.env : { ...process.env, ...(options.env || {}) },
89	      stdio: ['ignore', 'pipe', 'pipe'],
90	    });
91	    let stdout = '', stderr = '', timedOut = false;
92	    const max = options.maxBuffer || 4 * 1024 * 1024;
93	    const append = (current, chunk) => (current + chunk.toString()).slice(-max);
94	    child.stdout.on('data', (chunk) => { stdout = append(stdout, chunk); });
95	    child.stderr.on('data', (chunk) => { stderr = append(stderr, chunk); });
96	    const timer = options.timeoutMs ? setTimeout(() => {
97	      timedOut = true;
98	      child.kill('SIGTERM');
99	      setTimeout(() => child.kill('SIGKILL'), 3000).unref();
100	    }, options.timeoutMs) : null;
101	    child.on('error', reject);
102	    child.on('close', (code) => {
103	      if (timer) clearTimeout(timer);
104	      resolve({ code: code ?? 1, stdout, stderr, timedOut });
105	    });
106	  });
107	}
108	
109	async function runChecked(command, commandArgs, options = {}) {
110	  const result = await run(command, commandArgs, options);
111	  if (result.timedOut) throw new Error(`${command} timed out`);
112	  if (result.code !== 0) throw new Error((result.stderr || result.stdout || `${command} failed`).slice(-7000));
113	  return result.stdout;
114	}
115	
116	function loadParent() {
117	  if (!parentId) return null;
118	  if (!/^[a-z0-9-]{8,80}$/.test(parentId)) fail('invalid parent experiment id');
119	  const manifestPath = path.join(localRoot, `${parentId}.json`);
120	  const patchPath = path.join(localRoot, `${parentId}.patch`);
121	  if (!existsSync(manifestPath) || !existsSync(patchPath)) fail('parent experiment is unavailable on this dev machine');
122	  return {
123	    manifest: JSON.parse(readFileSync(manifestPath, 'utf8')),
124	    patchPath,
125	  };
126	}
127	
128	const FORBIDDEN = [
129	  [/\bfetch\s*\(/i, 'fetch'],
130	  [/\bXMLHttpRequest\b/i, 'XMLHttpRequest'],
131	  [/\bWebSocket\b/i, 'WebSocket'],
132	  [/\bEventSource\b/i, 'EventSource'],
133	  [/\bnavigator\.sendBeacon\b/i, 'sendBeacon'],
134	  [/\b(?:localStorage|sessionStorage|indexedDB|document\.cookie)\b/i, 'persistent storage'],
135	  [/\beval\s*\(/i, 'eval'],
136	  [/\bnew\s+Function\b/i, 'new Function'],
137	  [/\bimport\s*\(/i, 'dynamic import'],
138	  [/\bwindow\.open\s*\(/i, 'window.open'],
139	  [/\blocation\s*=|\blocation\.(?:href|assign|replace)\s*[=(]/i, 'navigation'],
140	];
141	
142	async function validateDiff(worktree, baseCommit) {
143	  const head = (await runChecked('git', ['rev-parse', 'HEAD'], { cwd: worktree })).trim();
144	  if (head !== baseCommit) fail('agent changed git history inside the disposable clone');
145	  const porcelain = await runChecked('git', ['status', '--porcelain=v1', '--untracked-files=all'], { cwd: worktree });
146	  // Do not trim the whole porcelain stream: the leading space in " M path"
147	  // is the first status column, not whitespace.
148	  const entries = porcelain.split('\n').filter((line) => line.length >= 4).map((line) => ({
149	    code: line.slice(0, 2),
150	    file: line.slice(3).split(' -> ').pop(),
151	  })).filter((entry) => entry.file !== 'node_modules'); // trusted dependency symlink created above
152	  const allChanged = [...new Set(entries.map((entry) => entry.file))];
153	  if (!allChanged.length) fail('agent made no code changes');
154	  for (const file of allChanged) {
155	    if (!/^marble-sort-swipe\/src\/[A-Za-z0-9._/-]+\.ts$/.test(file) || file.includes('..')) {
156	      fail(`agent touched forbidden path: ${file}`);
157	    }
158	  }
159	  const untracked = entries.filter((entry) => entry.code === '??').map((entry) => entry.file);
160	  if (untracked.length) await runChecked('git', ['add', '-N', '--', ...untracked], { cwd: worktree });
161	  const rawStatus = await runChecked('git', ['diff', '--name-status', '--', 'marble-sort-swipe/src'], { cwd: worktree });
162	  if (/^D\s/m.test(rawStatus)) fail('agent deleted a source file');
163	
164	  const patch = await runChecked('git', ['diff', '--binary', '--', 'marble-sort-swipe/src'], { cwd: worktree, maxBuffer: 1024 * 1024 });
165	  if (Buffer.byteLength(patch) > 350 * 1024) fail('experiment patch exceeds 350 KB');
166	  const numstat = await runChecked('git', ['diff', '--numstat', '--', 'marble-sort-swipe/src'], { cwd: worktree });
167	  const changedLines = numstat.trim().split('\n').filter(Boolean).reduce((sum, line) => {
168	    const [added, removed] = line.split('\t');
169	    return sum + (Number(added) || 0) + (Number(removed) || 0);
170	  }, 0);
171	  if (changedLines < 20) fail(`experiment is too small (${changedLines} changed lines); make a material rules/render/autoplay variation`);
172	
173	  for (const file of allChanged) {
174	    const source = readFileSync(path.join(worktree, file), 'utf8');
175	    for (const [pattern, label] of FORBIDDEN) if (pattern.test(source)) fail(`${file} uses forbidden capability: ${label}`);
176	    for (const match of source.matchAll(/(?:import|export)\s+(?:[^'";]+?\s+from\s+)?['"]([^'"]+)['"]/g)) {
177	      const specifier = match[1];
178	      if (specifier === 'matter-js' || specifier === '../../shared' || specifier === '../playable.config') continue;
179	      if (specifier.startsWith('./')) {
180	        const resolved = path.resolve(path.dirname(path.join(worktree, file)), specifier);
181	        const srcRoot = path.join(worktree, 'marble-sort-swipe', 'src') + path.sep;
182	        if (resolved.startsWith(srcRoot)) continue;
183	      }
184	      fail(`${file} imports forbidden dependency: ${specifier}`);
185	    }
186	  }
187	  return { patch, files: allChanged };
188	}
