190	function agentPrompt(attempt, failure) {
191	  const repair = failure
192	    ? `\nThe previous implementation failed the external gate. Diagnose and EDIT the code to fix it. Gate output:\n${failure.slice(-6000)}\n`
193	    : '';
194	  const lineage = parentId
195	    ? `This is a tuning pass over experiment ${parentId}. Player feedback: ${feedback || 'make the concept more distinctive without losing playability'}.`
196	    : 'This is the first implementation of the selected concept.';
197	  const toolBoundary = provider === 'claude'
198	    ? 'You have scoped Read/Edit only.'
199	    : 'You are inside a disposable workspace-write sandbox. The outer worker rejects every path outside marble-sort-swipe/src and runs build/autoplay itself.';
200	  return `You are implementing a deliberately surprising SWIPE-only variation of an existing marble-sort playable.
201	
202	Read marble-sort-swipe/src/main.ts and related files before editing. Then materially change the playable so it creates a different feeling through rules, interaction, physics, pacing, layout, or rendering. Do the implementation now; do not merely describe it.
203	
204	Player brief: ${prompt || 'surprise me'}
205	Selected concept: ${title}
206	Feeling: ${feeling}
207	Pitch: ${pitch}
208	Mechanic direction: ${mechanic}
209	${lineage}
210	
211	Hard executable contract:
212	- Edit ONLY TypeScript files under marble-sort-swipe/src/. This is the SWIPE mechanic; do not touch FTUE, AppLovin, shared, scripts, config, or other playables.
213	- Preserve bootstrap/lifecycle and the playable postMessage contract.
214	- ?auto=1 must autonomously understand your new rules, play the variant, and emit a successful completed event. Update its autoplay strategy when rules change.
215	- Manual play must remain possible and the canvas must remain responsive at 390px mobile width.
216	- No network, navigation, storage, eval, dynamic imports, new packages, or external assets.
217	- Keep runtime light enough for a mid-range Android. Avoid shadowBlur and unbounded particle/body creation.
218	- Strange is welcome. Broken is not. Do not reduce the experiment to a palette-only retheme.
219	- The resulting lineage patch must change at least 20 source lines; a few constants or colors are not an experiment.
220	
221	The outer worker, not you, runs build and Playwright. ${toolBoundary} Finish by briefly naming what changed.${repair}`;
222	}
223	
224	async function invokeAgent(worktree, attempt, failure) {
225	  const label = provider === 'codex' ? 'Codex' : 'Claude';
226	  status(attempt === 1 ? 'agent' : 'repair', attempt === 1 ? `${label} studies the pinned baseline and mutates the fork` : `${label} repairs the failed experiment`, attempt);
227	  const command = provider === 'codex' ? 'codex' : 'claude';
228	  const commandArgs = provider === 'codex'
229	    ? [
230	        '--sandbox', 'workspace-write',
231	        '--ask-for-approval', 'never',
232	        '-c', 'sandbox_workspace_write.network_access=false',
233	        '-C', worktree,
234	        'exec',
235	        '--ephemeral',
236	        '--ignore-user-config',
237	        '--ignore-rules',
238	        ...(CODEX_MODEL ? ['--model', CODEX_MODEL] : []),
239	        agentPrompt(attempt, failure),
240	      ]
241	    : [
242	        '--no-session-persistence',
243	        '--disable-slash-commands',
244	        '--permission-mode', 'default',
245	        '--tools', 'Read,Edit',
246	        '--allowedTools', 'Read(./marble-sort-swipe/**),Read(./shared/**),Edit(./marble-sort-swipe/src/**)',
247	        '--model', CLAUDE_MODEL,
248	        '--effort', EFFORT,
249	        '-p', agentPrompt(attempt, failure),
250	      ];
251	  const output = await run(command, commandArgs, {
252	    cwd: worktree,
253	    timeoutMs: AGENT_TIMEOUT_MS,
254	    maxBuffer: 1024 * 1024,
255	    env: subscriptionCliEnv(provider),
256	    replaceEnv: true,
257	  });
258	  if (output.timedOut) {
259	    status('agent-timeout', 'Coding timebox reached; testing the current patch', attempt);
260	    return output.stdout.trim().slice(-2000);
261	  }
262	  if (output.code !== 0) throw new Error((output.stderr || output.stdout || `${label} agent failed`).slice(-7000));
263	  return output.stdout.trim().slice(-2000);
264	}
265	
266	async function build(worktree, attempt) {
267	  status('build', 'Building the mutated SWIPE fork', attempt);
268	  const result = await run('bash', ['scripts/build-swipe.sh', 'marble-sort-swipe'], {
269	    cwd: worktree,
270	    timeoutMs: 180000,
271	    maxBuffer: 2 * 1024 * 1024,
272	  });
273	  if (result.timedOut) throw new Error('BUILD FAILED: build timed out');
274	  if (result.code !== 0) throw new Error(`BUILD FAILED\n${(result.stderr || result.stdout).slice(-7000)}`);
275	  const payload = path.join(worktree, 'marble-sort-swipe', 'dist-swipe', 'payload.js');
276	  if (!existsSync(payload)) throw new Error('BUILD FAILED: payload.js is missing');
277	  if (statSync(payload).size > 700 * 1024) throw new Error(`BUILD FAILED: payload is ${statSync(payload).size} bytes (limit 716800)`);
278	}
279	
280	async function autoplay(worktree, attempt) {
281	  status('test', 'Autoplay is trying to beat the new rules', attempt);
282	  const dist = path.join(worktree, 'marble-sort-swipe', 'dist-swipe');
283	  const server = createServer((req, res) => {
284	    const requested = decodeURIComponent((req.url || '/').split('?')[0]);
285	    const relative = requested === '/' ? 'index.html' : requested.replace(/^\//, '');
286	    const file = path.resolve(dist, relative);
287	    if (!file.startsWith(dist + path.sep) || !existsSync(file) || !statSync(file).isFile()) {
288	      res.statusCode = 404; res.end(); return;
289	    }
290	    res.setHeader('content-type', file.endsWith('.html') ? 'text/html; charset=utf-8' : 'application/javascript');
291	    res.end(readFileSync(file));
292	  });
293	  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
294	  const port = server.address().port;
295	  const { chromium } = await import('playwright');
296	  const browser = await chromium.launch();
297	  const errors = [];
298	  let lastState = null;
299	  try {
300	    const page = await browser.newPage({ viewport: { width: 390, height: 700 } });
301	    page.on('pageerror', (error) => errors.push(String(error)));
302	    page.on('console', (message) => { if (message.type() === 'error') errors.push(message.text()); });
303	    await page.addInitScript(() => {
304	      window.__events = [];
305	      window.addEventListener('message', (event) => {
306	        if (event.data && typeof event.data === 'object' && event.data.source === 'playable') {
307	          window.__events.push({ type: String(event.data.type || ''), success: event.data.success });
308	        }
309	      });
310	    });
311	    await page.goto(`http://127.0.0.1:${port}/?auto=1`, { waitUntil: 'domcontentloaded' });
312	    const deadline = Date.now() + TEST_TIMEOUT_MS;
313	    while (Date.now() < deadline) {
314	      lastState = await page.evaluate(() => ({
315	        canvas: Boolean(document.querySelector('canvas')),
316	        events: window.__events,
317	        debug: typeof window.__sortDebug === 'function' ? window.__sortDebug() : null,
318	      }));
319	      const won = lastState.events.some((event) => /complet|won|win/i.test(event.type) && event.success !== false);
320	      if (won) {
321	        if (errors.length) throw new Error(`AUTOPLAY ERRORS\n${errors.slice(0, 8).join('\n')}`);
322	        return;
323	      }
324	      await new Promise((resolve) => setTimeout(resolve, 500));
325	    }
326	  } finally {
327	    await browser.close();
328	    server.close();
329	  }
330	  if (!lastState?.canvas) {
331	    throw new Error(`RUNTIME FAILED: no canvas after ${Math.round(TEST_TIMEOUT_MS / 1000)}s\nstate=${JSON.stringify(lastState)}`);
332	  }
333	  if (errors.length) {
334	    throw new Error(`RUNTIME FAILED during autoplay\nerrors=${JSON.stringify(errors.slice(0, 8))}\nstate=${JSON.stringify(lastState)}`);
335	  }
336	  throw new AutoplayIncompleteError(`Autoplay did not prove a win within ${Math.round(TEST_TIMEOUT_MS / 1000)}s`);
337	}
338	
339	async function publishLocal(worktree, patch, files, baseCommit, attempts, agentSummary, autoplayPassed, gateError) {
340	  const digest = createHash('sha1').update(baseCommit).update('\0').update(patch).digest('hex').slice(0, 10);
341	  const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 24) || 'wild-sort';
342	  const id = `${slug}-${digest}`;
343	  mkdirSync(localRoot, { recursive: true });
344	  mkdirSync(artifactRoot, { recursive: true });
345	  const dist = path.join(worktree, 'marble-sort-swipe', 'dist-swipe');
346	  let html = readFileSync(path.join(dist, 'index.html'), 'utf8');
347	  const payload = readFileSync(path.join(dist, 'payload.js'), 'utf8').replace(/<\/script/gi, '<\\/script');
348	  const payloadTag = '<script type="module" src="./payload.js"></script>';
349	  if (!html.includes(payloadTag)) fail('experimental shell has no payload reference');
350	  // A single local HTML can run in an iframe sandbox without same-origin access
351	  // to the platform. It also keeps a lab result self-contained for tuning.
352	  html = html.replace(payloadTag, `<script type="module">${payload}</script>`);
353	  writeFileSync(path.join(artifactRoot, `${id}.html`), html);
354	  const extraFiles = readdirSync(dist).filter((file) => file !== 'index.html' && file !== 'payload.js');
355	  if (extraFiles.length) fail(`experimental build emitted unsupported external files: ${extraFiles.join(', ')}`);
356	  writeFileSync(path.join(localRoot, `${id}.patch`), patch);
357	  const manifest = {
358	    id,
359	    parentId: parentId || null,
360	    baselineId,
361	    baselineTree: baseline.sourceTree,
362	    provider,
363	    baseCommit,
364	    title,
365	    pitch,
366	    mechanic,
367	    feeling,
368	    prompt,
369	    feedback: feedback || null,
370	    attempts,
371	    autoplayPassed,
372	    gateError,
373	    files,
374	    agentSummary,
375	    createdAt: new Date().toISOString(),
376	    url: `/ugc/u/local-experiments/${id}.html`,
377	  };
378	  writeFileSync(path.join(localRoot, `${id}.json`), `${JSON.stringify(manifest, null, 2)}\n`);
379	  return manifest;
380	}
381	
382	let worktree = '';
383	try {
384	  if (!existsSync(path.join(playablesRoot, '.git'))) fail(`playables repo not found: ${playablesRoot}`);
385	  const parent = loadParent();
386	  const baseCommit = String(baseline.sourceCommit);
387	  const actualCommit = (await runChecked('git', ['rev-parse', `${baseCommit}^{commit}`], { cwd: playablesRoot })).trim();
388	  const actualTree = (await runChecked('git', ['rev-parse', `${baseCommit}:${baseline.sourcePath}`], { cwd: playablesRoot })).trim();
389	  if (actualCommit !== baseCommit || actualTree !== baseline.sourceTree) {
390	    fail(`generator baseline ${baselineId} failed its immutable commit/tree lock`);
391	  }
392	  if (parent) {
393	    const parentBaseline = parent.manifest.baselineId || (parent.manifest.baseCommit === baseCommit ? baselineId : '');
394	    if (parentBaseline !== baselineId) fail('parent experiment belongs to a different generator baseline');
395	  }
396	  worktree = mkdtempSync(path.join(tmpdir(), 'swipe-wild-sort-'));
397	  rmSync(worktree, { recursive: true, force: true });
398	  status('fork', parent ? 'Restoring the parent experiment in an isolated fork' : 'Creating an isolated mechanic fork');
399	  await runChecked('git', ['clone', '--shared', '--no-checkout', playablesRoot, worktree], { cwd: workspace, timeoutMs: 60000 });
400	  await runChecked('git', ['checkout', '--detach', baseCommit], { cwd: worktree, timeoutMs: 60000 });
401	  const cloneHead = (await runChecked('git', ['rev-parse', 'HEAD'], { cwd: worktree })).trim();
402	  if (cloneHead !== baseCommit) fail('disposable clone did not resolve the pinned baseline commit');
403	  const dependencies = path.join(playablesRoot, 'node_modules');
404	  if (!existsSync(dependencies)) fail('playables/node_modules is missing; run npm ci before starting the local lab');
405	  symlinkSync(dependencies, path.join(worktree, 'node_modules'), 'dir');
406	  if (parent) await runChecked('git', ['apply', '--whitespace=nowarn', parent.patchPath], { cwd: worktree });
407	
408	  let lastFailure = '', agentSummary = '', validated = null, wonAt = 0;
409	  let autoplayPassed = true, gateError = null;
410	  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
411	    try {
412	      agentSummary = await invokeAgent(worktree, attempt, lastFailure);
413	      status('safety', 'Checking the code sandbox and patch budget', attempt);
414	      validated = await validateDiff(worktree, baseCommit);
415	      if (parent && validated.patch === readFileSync(parent.patchPath, 'utf8')) {
416	        throw new Error('TUNING FAILED: Claude did not change the parent experiment');
417	      }
418	      await build(worktree, attempt);
419	      await autoplay(worktree, attempt);
420	      wonAt = attempt;
421	      break;
422	    } catch (error) {
423	      lastFailure = error instanceof Error ? error.message : String(error);
424	      if (error instanceof AutoplayIncompleteError && validated) {
425	        autoplayPassed = false;
426	        gateError = lastFailure;
427	        wonAt = attempt;
428	        status('soft-gate', 'Build is healthy, but autoplay could not prove a win; keeping the local experiment', attempt);
429	        break;
430	      }
431	      status('failed-attempt', lastFailure.slice(0, 360), attempt);
432	      if (attempt === MAX_ATTEMPTS) throw error;
433	    }
434	  }
435	  if (!validated || !wonAt) fail('experiment exhausted its repair budget');
436	  status('publish', autoplayPassed ? 'Autoplay won; saving the local experiment' : 'Saving the unverified local experiment', wonAt);
437	  const result = await publishLocal(worktree, validated.patch, validated.files, baseCommit, wonAt, agentSummary, autoplayPassed, gateError);
438	  console.log(`RESULT ${JSON.stringify(result)}`);
439	} catch (error) {
440	  console.error(`ERROR ${JSON.stringify({ error: error instanceof Error ? error.message : String(error) })}`);
441	  process.exitCode = 1;
442	} finally {
443	  if (worktree) rmSync(worktree, { recursive: true, force: true });
444	}
