// Profile mechanic-arrival jank in WebKit (iOS engine): rAF frame-gap sampler
// in the host + timestamps of series-row mutations and WAAPI starts, so gaps
// can be attributed. Swipes through several mechanics with real touch input.
import { createRequire } from 'module';
const require = createRequire('/Users/gleb/My projects/p4g-platform-workspace/package.json');
const { webkit } = require('playwright');

const SWIPES = Number(process.argv[2] || 5);
const browser = await webkit.launch();
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
const page = await ctx.newPage();

await page.addInitScript(() => {
  if (window !== window.top) return;   // host only
  const W = (window.__prof = { gaps: [], marks: [], t0: performance.now() });
  let last = performance.now();
  const tick = (now) => {
    const gap = now - last;
    if (gap > 34) W.gaps.push({ at: Math.round(now), gap: Math.round(gap) });
    last = now;
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
  const mark = (label) => W.marks.push({ at: Math.round(performance.now()), label });
  // WAAPI starts (chest bounce, slot pulse, halo, embers)
  const nativeAnimate = Element.prototype.animate;
  Element.prototype.animate = function (...args) {
    mark(`animate:${this.className || this.tagName}`.slice(0, 60));
    return nativeAnimate.apply(this, args);
  };
  // series-row lifecycle
  new MutationObserver((muts) => {
    for (const m of muts) {
      for (const n of m.addedNodes) {
        if (n.nodeType === 1 && n.classList?.contains('series-row')) mark('series-row:added');
        if (n.nodeType === 1 && n.classList?.contains('ember')) mark('ember:added');
      }
      if (m.type === 'attributes' && m.target.classList?.contains('series-row')) mark('series-row:' + m.target.className.replace(/\s+/g, '.'));
    }
  }).observe(document.documentElement, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });
});

const touch = (type, points) => page.evaluate(() => {}).then(() => null);
async function swipeUp() {
  await page.touchscreen.tap(195, 420).catch(() => {});
}

await page.goto('http://localhost:5199/?warm=1', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => !document.querySelector('.preloader'), null, { timeout: 20000 }).catch(() => {});
await page.waitForTimeout(1500);

const cdp = null;
async function dragUp() {
  // WebKit playwright supports touchscreen only for tap; use mouse fallback on
  // the autoplay veil (it listens to pointer events too).
  await page.mouse.move(195, 620);
  await page.mouse.down();
  for (let y = 620; y >= 200; y -= 42) { await page.mouse.move(195, y); await page.waitForTimeout(16); }
  await page.mouse.up();
}

const arrivals = [];
for (let s = 0; s < SWIPES; s++) {
  const before = await page.evaluate(() => performance.now());
  await dragUp();
  await page.waitForTimeout(3200);   // settle + reveal + autoplay start + series row + pulse window
  const data = await page.evaluate((since) => ({
    gaps: window.__prof.gaps.filter((gap) => gap.at >= since),
    marks: window.__prof.marks.filter((mark) => mark.at >= since),
  }), before);
  arrivals.push({ swipe: s + 1, ...data });
}
await browser.close();

for (const a of arrivals) {
  const big = a.gaps.filter((gap) => gap.gap >= 50);
  console.log(`── swipe ${a.swipe}: gaps>=34ms: ${a.gaps.length}, >=50ms: ${big.length}` +
    (big.length ? ` worst ${Math.max(...big.map((gap) => gap.gap))}ms` : ''));
  const t0 = Math.min(...[...a.gaps, ...a.marks].map((entry) => entry.at));
  const timeline = [...a.gaps.map((gap) => ({ at: gap.at, text: `GAP ${gap.gap}ms` })), ...a.marks.map((mark) => ({ at: mark.at, text: mark.label }))]
    .sort((x, y) => x.at - y.at);
  for (const entry of timeline) console.log(`   +${entry.at - t0}ms ${entry.text}`);
}

