1	// Collections (W-collections prototype): a "collection" is a set of 10 cards. A
2	// card is a layered visual — a stretchable cream background (bg_cards, 9-sliced
3	// via border-image so the uniform interior fills any size), the themed picture on
4	// top, and a ribbon at the bottom carrying the title text. Cards drop from the
5	// series chest (see feed.ts) and fly down into the collections button on the bar.
6	//
7	// Assets are inlined (vite assetsInlineLimit is effectively unlimited → single-file
8	// build). The 10 source pictures were 660×854 PNGs (~600 KB each); they're shipped
9	// here as width-400 q80 WebP (~15 KB each) so the whole set adds <200 KB to the
10	// bundle instead of ~6 MB.
11	import BG_CARDS from './assets/collections/bg_cards.png';
12	import RIBBON from './assets/collections/ribbon_title.webp';
13	import CARD_01 from './assets/collections/collection_1/card_01.webp';
14	import CARD_02 from './assets/collections/collection_1/card_02.webp';
15	import CARD_03 from './assets/collections/collection_1/card_03.webp';
16	import CARD_04 from './assets/collections/collection_1/card_04.webp';
17	import CARD_05 from './assets/collections/collection_1/card_05.webp';
18	import CARD_06 from './assets/collections/collection_1/card_06.webp';
19	import CARD_07 from './assets/collections/collection_1/card_07.webp';
20	import CARD_08 from './assets/collections/collection_1/card_08.webp';
21	import CARD_09 from './assets/collections/collection_1/card_09.webp';
22	import CARD_10 from './assets/collections/collection_1/card_10.webp';
23	
24	export const CARD_BG = BG_CARDS;
25	export const CARD_RIBBON = RIBBON;
26	
27	// border-image slice for bg_cards.png (273×273): captures the ~13 px soft glow
28	// plus the rounded corner; the interior past this is a uniform cream fill, so the
29	// centre stretches seamlessly to any card size.
30	export const CARD_BG_SLICE = 70;
31	
32	export interface CollectionCard {
33	  /** stable id within its collection, 1-based */
34	  index: number;
35	  img: string;
36	  /** label rendered on the card ribbon */
37	  title: string;
38	}
39	
40	export interface Collection {
41	  id: string;
42	  title: string;
43	  subtitle: string;
44	  /** reward granted after every card in the collection is gathered */
45	  rewardPuzzles: number;
46	  cards: CollectionCard[];
47	}
48	
49	const COLLECTION_1_PICS = [
50	  CARD_01, CARD_02, CARD_03, CARD_04, CARD_05,
51	  CARD_06, CARD_07, CARD_08, CARD_09, CARD_10,
52	];
53	
54	const COLLECTION_1_TITLES = [
55	  'Виниловый хит',
56	  'Кассетный плеер',
57	  'Радиоволна',
58	  'Золотой микрофон',
59	  'Электрогитара',
60	  'Диско-шар',
61	  'Бумбокс',
62	  'Музыкальная награда',
63	  'Джукбокс',
64	  'Король сцены',
65	];
66	
67	export const COLLECTIONS: Collection[] = [
68	  {
69	    id: 'collection_1',
70	    title: 'Золотые хиты',
71	    subtitle: 'Музыка сквозь время',
72	    rewardPuzzles: 150,
73	    cards: COLLECTION_1_PICS.map((img, i) => ({
74	      index: i + 1,
75	      img,
76	      title: COLLECTION_1_TITLES[i],
77	    })),
78	  },
79	];
80	
81	// Collection progress is intentionally separate from the chest-drop animation.
82	// Only compact card indexes are stored: the imported card images are inlined as
83	// data URLs in production and must never be copied into localStorage.
84	export interface CollectionProgress {
85	  collectedCardIndexes: number[];
86	}
87	
88	export interface CollectionsProgressState {
89	  version: 1;
90	  byCollection: Record<string, CollectionProgress>;
91	}
92	
93	const COLLECTIONS_PROGRESS_KEY = 'collections-progress-v1';
94	const DEMO_COLLECTED: Record<string, number[]> = {
95	  // A partial state makes both collected and missing treatments visible until
96	  // real season progress starts arriving from the product/backend.
97	  collection_1: [1, 2, 4, 7],
98	};
99	
100	function defaultProgressFor(collectionId: string): CollectionProgress {
101	  return { collectedCardIndexes: [...(DEMO_COLLECTED[collectionId] ?? [])] };
102	}
103	
104	export function defaultCollectionsProgressState(): CollectionsProgressState {
105	  const byCollection: Record<string, CollectionProgress> = {};
106	  COLLECTIONS.forEach((collection) => {
107	    byCollection[collection.id] = defaultProgressFor(collection.id);
108	  });
109	  return { version: 1, byCollection };
110	}
111	
112	function normaliseProgress(value: unknown): CollectionsProgressState {
113	  const parsed = value && typeof value === 'object'
114	    ? value as Partial<CollectionsProgressState>
115	    : {};
116	  const source = parsed.byCollection && typeof parsed.byCollection === 'object'
117	    ? parsed.byCollection
118	    : {};
119	  const byCollection: Record<string, CollectionProgress> = {};
120	
121	  COLLECTIONS.forEach((collection) => {
122	    const entry = source[collection.id];
123	    if (!entry || !Array.isArray(entry.collectedCardIndexes)) {
124	      byCollection[collection.id] = defaultProgressFor(collection.id);
125	      return;
126	    }
127	    const allowed = new Set(collection.cards.map((card) => card.index));
128	    const indexes = entry.collectedCardIndexes
129	      .filter((index): index is number => Number.isInteger(index) && allowed.has(index))
130	      .filter((index, pos, all) => all.indexOf(index) === pos)
131	      .sort((a, b) => a - b);
132	    byCollection[collection.id] = { collectedCardIndexes: indexes };
133	  });
134	
135	  return { version: 1, byCollection };
136	}
137	
138	export function saveCollectionsProgressState(state: CollectionsProgressState): void {
139	  try {
140	    localStorage.setItem(COLLECTIONS_PROGRESS_KEY, JSON.stringify(normaliseProgress(state)));
141	  } catch { /* storage can be blocked in private/embedded contexts */ }
142	}
143	
144	export function loadCollectionsProgressState(): CollectionsProgressState {
145	  try {
146	    const raw = localStorage.getItem(COLLECTIONS_PROGRESS_KEY);
147	    const state = raw ? normaliseProgress(JSON.parse(raw) as unknown) : defaultCollectionsProgressState();
148	    // Re-cache the normalised shape so corrupt/old/future entries cannot leak into
149	    // the runtime state, and the first-run demo progress survives a reload.
150	    saveCollectionsProgressState(state);
151	    return state;
