    publishing: bool = False
    publishError: str | None = Field(default=None, max_length=1000)
    jobId: str | None = Field(default=None, pattern=r"^[0-9a-fA-F-]{36}$")
    rel: str | None = Field(default=None, max_length=320)
    url: str | None = Field(default=None, max_length=600)

    @field_validator("pack")
    @classmethod
    def _building_pack_id(cls, value: str) -> str:
        if not PACK_ID_RE.fullmatch(value):
            raise ValueError("building pack id contains unsupported characters")
        return value

    @field_validator("rel")
    @classmethod
    def _hosted_rel(cls, value: str | None) -> str | None:
        if value is not None and not REL_RE.fullmatch(value):
            raise ValueError("hosted rel must be a published UGC html path")
        return value

    @field_validator("url")
    @classmethod
    def _hosted_url(cls, value: str | None) -> str | None:
        if value is not None and not (
            value.startswith("https://")
            or value.startswith("http://localhost")
            or value.startswith("http://127.0.0.1")
            or value.startswith("/ugc/")
            or value.startswith("ugc/")
        ):
            raise ValueError("hosted url must use https, localhost, or /ugc")
        return value


class IslandStateData(BaseModel):
    model_config = ConfigDict(extra="forbid")

    tokens: int = Field(default=120, ge=0, le=2_000_000_000)
    buildings: list[IslandBuilding] = Field(default_factory=list, max_length=4)
    aiPacks: dict[str, IslandPack] | None = Field(default=None, max_length=64)
    aiSeq: int | None = Field(default=None, ge=0, le=2_000_000_000)

    @model_validator(mode="after")
    def _consistent(self) -> "IslandStateData":
        slots = [building.slot for building in self.buildings]
        if len(slots) != len(set(slots)):
            raise ValueError("island building slots must be unique")
        for key, pack in (self.aiPacks or {}).items():
            if key != pack.id:
                raise ValueError("aiPacks keys must match pack ids")
        return self


class IslandStatePut(BaseModel):
    model_config = ConfigDict(extra="forbid")

    expected_revision: int = Field(ge=0)
    state: IslandStateData


def _view(record: IslandStateRecord | None) -> dict:
    if record is None:
        return {
            "state": None,
            "revision": 0,
            "schema_version": STATE_SCHEMA_VERSION,
            "updated_at": None,
        }
    state = IslandStateData.model_validate(record.data).model_dump(mode="json", exclude_none=True)
    return {
        "state": state,
        "revision": int(record.revision),
        "schema_version": int(record.schema_version),
        "updated_at": record.updated_at.isoformat(),
    }


def _conflict(db: Session, user_id: int) -> None:
    current = db.get(IslandStateRecord, user_id)
    raise HTTPException(
        status_code=409,
        detail={
            "code": "island_revision_conflict",
            "current_revision": int(current.revision) if current else 0,
        },
    )


def _payload_for_user(state: IslandStateData, user_id: int) -> dict:
    for building in state.buildings:
        if building.rel and not building.rel.startswith(f"u/{user_id}/"):
            raise HTTPException(status_code=422, detail="hosted artifact belongs to another user")
    return state.model_dump(mode="json", exclude_none=True)


@router.get("/island/state")
def get_island_state(
    caller: TmaUser = Depends(require_tma_user),
    db: Session = Depends(get_db),
) -> dict:
    return _view(db.get(IslandStateRecord, caller.id))


@router.put("/island/state")
def put_island_state(
    body: IslandStatePut,
    caller: TmaUser = Depends(require_tma_user),
    db: Session = Depends(get_db),
) -> dict:
    payload = _payload_for_user(body.state, caller.id)

