"""Canonical server policy for gameplay series tickets."""
from __future__ import annotations


def mechanic_base_id(mechanic_id: str) -> str:
    return mechanic_id[:-6] if mechanic_id.endswith("-swipe") else mechanic_id


def series_length(mechanic_id: str) -> int:
    base = mechanic_base_id(mechanic_id)
    if base == "pins-l3" or base == "pins" or base.startswith("pins-"):
        return 2
    if base == "merge-locked-v1":
        return 1
    if base == "marble-sort":
        return 2
    if base == "merge-timepress-v1":
        return 2
    if base == "merge-timepress-v2":
        return 1
    if base == "short-drama":
        return 6
    if "no-orders" in base or "second-board" in base:
        return 1
    return 5
"""Shared run-ticket timing and lookup helpers."""
from __future__ import annotations

import uuid
from datetime import datetime, timedelta, timezone

from fastapi import HTTPException
from sqlalchemy.orm import Session

from .config import Settings
from .models import RunTicket, VerifiedRun


def utc_now() -> datetime:
    return datetime.now(timezone.utc)


def next_result_at(ticket: RunTicket, min_result_ms: int) -> datetime:
    anchor = ticket.last_result_at or ticket.created_at
    if anchor.tzinfo is None:
        anchor = anchor.replace(tzinfo=timezone.utc)
    return anchor + timedelta(milliseconds=max(0, min_result_ms))


def legacy_results_allowed(settings: Settings, now: datetime | None = None) -> bool:
    cutoff = settings.run_ticket_legacy_until
    if cutoff is None:
        return False
    if cutoff.tzinfo is None:
        cutoff = cutoff.replace(tzinfo=timezone.utc)
    return (now or utc_now()) < cutoff


def verified_run(
    db: Session,
    *,
    user_id: int,
    run_id: str,
    mechanic_id: str | None = None,
    variant_id: uuid.UUID | None = None,
) -> VerifiedRun:
    run = db.get(VerifiedRun, run_id)
    if run is None or run.user_id != user_id:
        raise HTTPException(status_code=404, detail="verified run not found")
    if mechanic_id is not None and run.mechanic_id != mechanic_id:
        raise HTTPException(status_code=409, detail="verified run mechanic mismatch")
    if variant_id is not None and run.variant_id != variant_id:
        raise HTTPException(status_code=409, detail="verified run variant mismatch")
    if run.metric_key != "time_ms":
        raise HTTPException(status_code=409, detail="verified run has no solve-time metric")
    return run

