    return anchor + timedelta(milliseconds=max(0, min_result_ms))


def legacy_results_allowed(settings: Settings, now: datetime | None = None) -> bool:
    cutoff = settings.run_ticket_legacy_until
    if cutoff is None:
        return False
    if cutoff.tzinfo is None:
        cutoff = cutoff.replace(tzinfo=timezone.utc)
    return (now or utc_now()) < cutoff


def verified_run(
    db: Session,
    *,
    user_id: int,
    run_id: str,
    mechanic_id: str | None = None,
    variant_id: uuid.UUID | None = None,
) -> VerifiedRun:
    run = db.get(VerifiedRun, run_id)
    if run is None or run.user_id != user_id:
        raise HTTPException(status_code=404, detail="verified run not found")
    if mechanic_id is not None and run.mechanic_id != mechanic_id:
        raise HTTPException(status_code=409, detail="verified run mechanic mismatch")
    if variant_id is not None and run.variant_id != variant_id:
        raise HTTPException(status_code=409, detail="verified run variant mismatch")
    if run.metric_key != "time_ms":
        raise HTTPException(status_code=409, detail="verified run has no solve-time metric")
    return run

