import { createHash } from 'node:crypto';
import { isDeepStrictEqual } from 'node:util';

import { canonicalizeEvaluationJson, listEvaluationOutboxItems } from './evaluation-outbox.mjs';
import { listReviews } from './lab-store.mjs';
import { projectLevelReviewQueue } from './level-review.mjs';
import { listLevelQaChildren } from './levels-qa-children.mjs';
import { listJobs } from './store.mjs';

const HEX_DIGEST = /^[a-f0-9]{64}$/;
const PREFIXED_DIGEST = /^sha256:[a-f0-9]{64}$/;
const UUID = /^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;
const REVIEW_TARGET = /^level-[a-f0-9]{64}$/;
const DIFFICULTIES = new Set(['easy', 'medium', 'hard', 'expert']);
const MAX_LEVELS = 6;
const ID_NAMESPACE = '6cbac2d9-3b17-5a87-b1d2-b7ef39cebb21';

function composerError(code, message) {
  const error = new Error(String(message).replace(/\s+/g, ' ').trim().slice(0, 2000));
  error.code = code;
  return error;
}

function sha256Jcs(value) {
  return createHash('sha256').update(canonicalizeEvaluationJson(value), 'utf8').digest('hex');
}

function uuidBytes(value) {
  if (!UUID.test(String(value || ''))) throw composerError('catalog_series_internal', 'UUID namespace is invalid');
  return Buffer.from(value.replaceAll('-', ''), 'hex');
}

function uuidV5(namespace, name) {
  const bytes = createHash('sha1')
    .update(uuidBytes(namespace))
    .update(Buffer.from(String(name), 'utf8'))
    .digest()
    .subarray(0, 16);
  bytes[6] = (bytes[6] & 0x0f) | 0x50;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = bytes.toString('hex');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

function normalizeReason(value) {
  const reason = String(value || '').trim().replace(/\s+/g, ' ');
  if (!reason || reason.length > 512 || Buffer.byteLength(reason, 'utf8') > 2048
    || /[\u0000-\u001f\u007f]/.test(reason)) {
    throw composerError('catalog_series_invalid', 'promotion reason must be 1 to 512 printable characters');
  }
  return reason;
}

function assertOrderedTargets(value) {
  if (!Array.isArray(value) || value.length < 1 || value.length > MAX_LEVELS) {
    throw composerError('catalog_series_invalid', 'choose 1 to 6 ordered level review targets');
  }
  const targets = value.map((item) => String(item || ''));
  if (targets.some((item) => !REVIEW_TARGET.test(item))) {
    throw composerError('catalog_series_invalid', 'every review target must be an immutable level-<sha256> id');
