 * Wait for the one allowed catalog configuration message. Untrusted source,
 * origin, envelope, id, and nonce traffic cannot configure the game; the first
 * trusted response consumes the nonce and is frozen after full validation.
 */
export async function prepareSortCatalogSession(options: PrepareCatalogOptions): Promise<SortCatalogSession> {
  const configMode = new URL(options.href).searchParams.get('level_config');
  if (configMode === null) return { mode: 'legacy', spec: null, acknowledge() {}, fail() {} };
  if (configMode !== 'catalog_required') {
    catalogMarker(options.href); // throws the stable invalid_marker error
    throw new SortLevelRuntimeError('invalid_marker', 'unsupported level_config');
  }

  const expectedOrigin = parentOrigin(options.referrer);
  const runtimeWindow = options.runtimeWindow;
  const parent = runtimeWindow.parent;
  if (!parent || parent === (runtimeWindow as unknown as RuntimeParent)) {
    throw new SortLevelRuntimeError('parent_unavailable', 'Catalog mode requires an embedding parent');
  }
  let terminal = false;

  const postFailure = (reason: CatalogFailureReason) => {
    if (terminal) return;
    parent.postMessage({
      type: 'configure_failed',
      reason,
    }, expectedOrigin);
    terminal = true;
  };

  let marker: { required: true; expectedSpecHash: string };
  try {
    const parsed = catalogMarker(options.href);
    if (!parsed.required) throw new SortLevelRuntimeError('invalid_marker', 'catalog_required marker disappeared');
    marker = parsed;
  } catch (error) {
    try { postFailure('digest'); } catch { /* preserve marker failure */ }
    throw error;
  }

  const cryptoImpl = options.cryptoImpl || globalThis.crypto;
  let nonce: string;
  try { nonce = runtimeNonce(cryptoImpl); } catch (error) {
    try { postFailure('runtime'); } catch { /* preserve crypto failure */ }
    throw error;
  }
  const timeoutMs = Math.max(100, Math.min(15000, options.timeoutMs ?? 4000));
  const runtimeArtifactDigest = String(options.runtimeArtifactDigest || '');

  if (!validArtifactDigest(runtimeArtifactDigest)) {
    try { postFailure('runtime'); } catch { /* throw stable local error below */ }
    throw new SortLevelRuntimeError('runtime_artifact_digest_unavailable', 'Catalog mode requires a release-supplied runtimeArtifactDigest');
  }

  const spec = await new Promise<SortLevelSpec>((resolve, reject) => {
    let settled = false;
    let sawRejectedOrigin = false;
    let timer = 0;
    const cleanup = () => {
      runtimeWindow.removeEventListener('message', onMessage);
      if (timer) clearTimeout(timer);
    };
    const finishError = (error: unknown, reason: CatalogFailureReason) => {
      if (settled) return;
      settled = true;
      cleanup();
      try { postFailure(reason); } catch { /* preserve the initiating failure */ }
      reject(error);
    };
    const onMessage = (event: MessageEvent) => {
      if (settled || event.source !== parent) return;
      if (event.origin !== expectedOrigin) { sawRejectedOrigin = true; return; }
      if (!isPlainObject(event.data)) return;
      const data = event.data;
      if (!hasExactKeys(data, ['type', 'nonce', 'spec'])
        || data.type !== 'configure_level'
        || data.nonce !== nonce) return;
      settled = true;
      cleanup();
      void validateSortLevelSpec(data.spec, cryptoImpl).then((checked) => {
        if (checked.specHash !== marker.expectedSpecHash) {
          try { postFailure('digest'); } catch { /* reject below */ }
          reject(new SortLevelRuntimeError('spec_mismatch', 'Catalog LevelSpec does not match expected_spec_hash'));
          return;
        }
        resolve(checked);
      }, (error) => {
        try { postFailure(specFailureReason(error)); } catch { /* reject below */ }
        reject(error);
      });
    };
    runtimeWindow.addEventListener('message', onMessage);
    timer = setTimeout(() => finishError(
      new SortLevelRuntimeError('catalog_timeout', 'Timed out waiting for catalog LevelSpec'),
      sawRejectedOrigin ? 'origin' : 'timeout',
    ), timeoutMs) as unknown as number;
    try {
      parent.postMessage({
        type: 'configure_ready',
        nonce,
        runtimeContractDigest: SORT_RUNTIME_CONTRACT_DIGEST,
        runtimeArtifactDigest,
      }, expectedOrigin);
    } catch (error) {
      finishError(error, 'runtime');
    }
  });

  return {
    mode: 'catalog',
    spec,
    nonce,
    expectedOrigin,
    acknowledge() {
      if (terminal) return;
      parent.postMessage({
        type: 'configured',
        appliedSpecHash: spec.specHash,
        runtimeContractDigest: SORT_RUNTIME_CONTRACT_DIGEST,
        runtimeArtifactDigest,
      }, expectedOrigin);
      terminal = true;
    },
    fail(reason: CatalogFailureReason = 'mount') {
      postFailure(reason);
    },
  };
}

export function renderSortCatalogFailure(reason: string, targetDocument: Document = document): void {
  targetDocument.documentElement.dataset.catalogState = 'failed';
  targetDocument.documentElement.dataset.catalogFailure = reason.slice(0, 80);
  const existing = targetDocument.getElementById('sort-catalog-failure');
  if (existing) return;
  const cover = targetDocument.createElement('div');
  cover.id = 'sort-catalog-failure';
  cover.setAttribute('role', 'alert');
  cover.textContent = 'Level unavailable';
  cover.style.cssText = 'position:fixed;inset:0;z-index:2147483647;display:grid;place-items:center;' +
    'background:#5B6B8A;color:#fff;font:700 18px/1.3 system-ui,sans-serif;pointer-events:auto';
  targetDocument.body.appendChild(cover);

