import { isDeepStrictEqual } from 'node:util';

import { normaliseQaRuntimeSnapshot } from './levels-qa-children.mjs';
import { loadSortLevelContract } from './levels-job.mjs';

const UUID = /^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;
const HASH = /^[a-f0-9]{64}$/;
const PREFIXED_HASH = /^sha256:[a-f0-9]{64}$/;
const REVIEW_TARGET = /^level-[a-f0-9]{64}$/;
const DIFFICULTIES = new Set(['easy', 'medium', 'hard', 'expert']);
const INPUT_KEYS = ['expectedParentSpecHash', 'mutationId', 'params', 'parentReviewTargetId', 'reason'];
const DERIVATION_KEYS = [
  'actor', 'compilerDigest', 'derivedRecipeDigest', 'editKind', 'mutationId',
  'parentEvaluationId', 'parentRecipeDigest', 'parentReviewTargetId',
  'parentRuntimeArtifactDigest', 'parentSpecHash', 'reason', 'requestHash',
  'schema', 'spec',
];

function deriveError(code, message, statusCode = 400, details = null) {
  const error = new Error(String(message).replace(/\s+/g, ' ').trim().slice(0, 2000));
  error.code = code;
  error.statusCode = statusCode;
  if (details) error.details = details;
  return error;
}

function clone(value, label, maxBytes = 128 * 1024) {
  let encoded;
  try { encoded = JSON.stringify(value); } catch { throw deriveError('level_derivation_invalid', `${label} must be JSON`); }
  if (!encoded || Buffer.byteLength(encoded) > maxBytes) {
    throw deriveError('level_derivation_invalid', `${label} is too large`);
  }
  return JSON.parse(encoded);
}

function exactKeys(value, expected, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)
    || !isDeepStrictEqual(Object.keys(value).sort(), expected)) {
    throw deriveError('level_derivation_invalid', `${label} must contain exactly ${expected.join(', ')}`);
  }
}

function cleanReason(value) {
  const reason = String(value || '').trim().replace(/\s+/g, ' ');
  if (!reason || reason.length > 512 || Buffer.byteLength(reason, 'utf8') > 2048
    || /[\u0000-\u001f\u007f]/.test(reason)) {
    throw deriveError('level_derivation_invalid', 'reason must be 1 to 512 printable characters');
  }
  return reason;
}

